window.BOOK = [{"n":1,"t":"세상의 시작","sub":"아무것도 없던 때, 세상이 하나씩 생겨나요","b":[{"k":"img","i":0,"f":"images/scenes/c01-00.png","cap":"장 표지","who":["chaos","gaia","uranus","nyx","eros"]},{"k":"p","t":"아주아주 먼 옛날, 아직 아무것도 없던 때가 있었어요. 땅도 하늘도 바다도 없고, 해도 달도 별도 없었지요. 옛 그리스 사람들은 세상이 어떻게 시작되었는지 궁금해서 이런 이야기를 지어 전했어요. 이제부터 그 이야기를 처음부터 차례차례 들려줄게요."},{"k":"who","id":"chaos"},{"k":"p","t":"맨 처음에는 끝없이 텅 빈 틈만 있었어요. 그 틈의 이름이 카오스예요. 안개처럼 뿌옇고 소용돌이처럼 빙글빙글 도는, 아무 모양도 없는 곳이었지요."},{"k":"img","i":1,"f":"images/scenes/c01-01.png","cap":"텅 빈 틈에서 가이아가 깨어나는 장면","who":["chaos","gaia"]},{"k":"who","id":"gaia"},{"k":"p","t":"그 텅 빈 틈에서 가장 먼저 깨어난 것은 대지의 여신 가이아였어요. 가이아가 기지개를 켜자 발밑에 넓은 땅이 펼쳐졌어요. 가이아가 손을 뻗는 곳마다 풀이 돋고, 나무가 자라고, 꽃이 피어났지요. 세상 모든 것이 서 있을 든든한 땅이 생긴 거예요."},{"k":"who","id":"tartarus"},{"k":"who","id":"eros"},{"k":"p","t":"땅 아래 가장 깊은 곳에는 어둡고 깊은 구덩이 타르타로스가 생겨났어요. 그리고 무언가와 무언가를 서로 끌어당기는 힘, 사랑의 신 에로스도 태어났어요. 에로스가 있어서 세상의 것들이 서로 만나 새로운 것을 낳을 수 있게 되었대요."},{"k":"img","i":3,"f":"images/scenes/c01-03.png","cap":"밤의 여신 닉스가 날개를 펴는 장면","who":["nyx","erebus"]},{"k":"who","id":"nyx"},{"k":"who","id":"erebus"},{"k":"p","t":"카오스에서는 어둠의 신 에레보스와 밤의 여신 닉스도 태어났어요. 닉스가 커다란 검은 날개를 펼치면 세상은 조용하고 까만 밤이 되었지요. 그리고 닉스와 에레보스 사이에서는 반짝이는 하늘 높은 곳의 빛 아이테르와 환한 낮 헤메라가 태어났어요. 그래서 밤이 지나면 낮이 오게 되었대요."},{"k":"img","i":2,"f":"images/scenes/c01-02.png","cap":"하늘 우라노스가 대지를 감싸는 장면","who":["uranus","gaia"]},{"k":"who","id":"uranus"},{"k":"p","t":"가이아는 혼자서 별이 총총한 하늘 우라노스를 낳았어요. 우라노스는 둥근 지붕처럼 대지를 빙 둘러 덮었지요. 가이아는 높은 산들과 넓은 바다 폰토스도 낳았어요. 이제 세상에는 땅과 하늘과 바다가 모두 생겼어요."},{"k":"p","t":"가이아와 우라노스는 부부가 되어 많은 아이를 낳았어요. 먼저 키가 크고 힘센 티탄 열두 남매가 태어났어요. 그다음에는 이마에 둥근 눈이 하나뿐인 거인 키클롭스 삼형제가 태어났고, 팔이 백 개나 달린 거인 헤카톤케이레스 삼형제도 태어났어요."},{"k":"p","t":"그런데 우라노스는 외눈 거인과 팔 백 개 거인 아이들이 너무 크고 힘이 세서 무서웠어요. 그래서 아이들을 가이아의 배 속, 땅속 깊은 곳에 가둬 버렸지요. 아이들이 갇혀서 가이아는 몸도 마음도 몹시 아팠어요. \"이대로는 안 되겠어. 누가 나를 도와줄까?\" 가이아는 티탄 아이들을 불러 모았어요. 다음 장에서는 그중 누가 용감하게 나섰는지 알아볼 거예요."}],"q":[{"q":"세상이 생기기 전 맨 처음에 있었던 텅 빈 틈의 이름은?","o":["가이아","카오스","닉스","에로스"],"a":1,"e":"카오스는 안개처럼 뿌옇고 소용돌이치는 텅 빈 틈이었어요. 모든 것이 여기서 시작되었지요."},{"q":"텅 빈 틈에서 가장 먼저 깨어나 땅이 된 여신은?","o":["가이아","닉스","헤메라","레아"],"a":0,"e":"대지의 여신 가이아가 깨어나자 땅이 펼쳐지고 풀과 나무가 자라났어요."},{"q":"커다란 검은 날개를 펼쳐 세상을 밤으로 만드는 여신은?","o":["헤메라","가이아","닉스","아이테르"],"a":2,"e":"밤의 여신 닉스가 날개를 펼치면 세상이 조용하고 까만 밤이 되었어요."},{"q":"가이아가 낳은, 별이 총총한 하늘의 신은?","o":["에레보스","폰토스","타르타로스","우라노스"],"a":3,"e":"하늘 우라노스는 둥근 지붕처럼 대지를 덮었어요."},{"q":"우라노스가 땅속 깊은 곳에 가둬 버린 아이들은?","o":["티탄 열두 남매","외눈 거인과 팔 백 개 거인","바다의 요정들","밤과 낮"],"a":1,"e":"우라노스는 키클롭스와 헤카톤케이레스가 너무 크고 힘이 세서 무서워 땅속에 가뒀어요."}]},{"n":2,"t":"티탄의 시대","sub":"크로노스가 왕이 되고, 아기 제우스가 숨겨져요","b":[{"k":"img","i":0,"f":"images/scenes/c02-00.png","cap":"장 표지","who":["cronus","rhea","oceanus","hyperion","themis","mnemosyne"]},{"k":"who","id":"cronus"},{"k":"p","t":"가이아의 부름에 티탄 열두 남매가 모였지만, 모두 아버지 우라노스가 무서워서 고개를 숙였어요. 그때 막내 크로노스가 앞으로 나섰어요. \"제가 할게요, 어머니!\""},{"k":"img","i":1,"f":"images/scenes/c02-01.png","cap":"가이아가 크로노스에게 커다란 낫을 건네는 장면","who":["gaia","cronus"]},{"k":"p","t":"가이아는 단단한 돌로 커다란 낫을 만들어 크로노스에게 건넸어요. 밤이 되어 우라노스가 대지를 덮으러 내려오자, 숨어 있던 크로노스가 낫을 휘둘러 아버지에게 맞섰지요. 깜짝 놀란 우라노스는 하늘 높이 달아나 다시는 대지를 짓누르지 못했어요. 그 뒤로 하늘과 땅 사이가 넓게 벌어져, 그 사이에서 모든 것이 자랄 수 있게 되었대요."},{"k":"p","t":"이렇게 크로노스는 세상의 새 왕이 되었어요. 티탄들이 세상을 다스리는 티탄의 시대가 시작된 거예요."},{"k":"who","id":"oceanus"},{"k":"who","id":"hyperion"},{"k":"who","id":"themis"},{"k":"who","id":"mnemosyne"},{"k":"p","t":"티탄들은 저마다 맡은 일이 있었어요. 오케아노스는 세상 가장자리를 빙 둘러 흐르는 큰 강을 다스렸고, 히페리온은 하늘 높은 곳의 빛을 다스렸어요. 테미스는 옳고 그름과 세상의 질서를 지켰고, 므네모시네는 모든 것을 기억하는 기억의 여신이었지요."},{"k":"p","t":"하지만 크로노스는 약속을 지키지 않았어요. 땅속에 갇힌 외눈 거인 키클롭스와 팔 백 개 거인들을 꺼내 주지 않고, 오히려 더 깊은 타르타로스에 가둬 버렸거든요. 가이아는 화가 나서 이렇게 말했어요. \"크로노스, 너도 언젠가 네 아이에게 왕 자리를 빼앗길 거란다.\""},{"k":"img","i":2,"f":"images/scenes/c02-02.png","cap":"크로노스가 아기들을 삼키는 장면 (무섭지 않게)","who":["cronus","rhea"]},{"k":"who","id":"rhea"},{"k":"p","t":"크로노스는 누이 레아와 결혼했어요. 그런데 어머니의 말이 자꾸 떠올라 걱정이 되었지요. 그래서 크로노스는 아주 이상한 방법을 생각해 냈어요. 레아가 아기를 낳을 때마다 아기를 꿀꺽 삼켜 버린 거예요! 헤스티아, 데메테르, 헤라, 하데스, 포세이돈, 다섯 아기가 모두 크로노스의 배 속으로 들어갔어요. 신들은 죽지 않기 때문에 아기들은 배 속에서 무럭무럭 자랐대요."},{"k":"img","i":3,"f":"images/scenes/c02-03.png","cap":"레아가 포대기에 싼 돌을 건네는 장면","who":["rhea","cronus"]},{"k":"p","t":"레아는 너무 슬펐어요. 여섯 번째 아기를 가졌을 때, 레아는 가이아와 우라노스를 찾아가 도움을 청했어요. 그리고 좋은 꾀를 얻었지요. 아기가 태어나자, 레아는 커다란 돌을 포대기에 곱게 싸서 크로노스에게 건넸어요. 크로노스는 돌인 줄도 모르고 꿀꺽 삼켰답니다."},{"k":"img","i":4,"f":"images/scenes/c02-04.png","cap":"크레타 동굴에서 님프들이 아기 제우스를 돌보는 장면","who":["zeus"]},{"k":"who","id":"zeus"},{"k":"p","t":"진짜 아기는 멀리 크레타섬의 깊은 동굴에 숨겨졌어요. 그 아기의 이름이 바로 제우스예요. 동굴에서는 상냥한 님프들이 아기를 돌보았고, 착한 염소가 젖을 주었어요. 아기가 울음을 터뜨리면, 밖에서 젊은 전사들이 방패를 창으로 쾅쾅 두드리며 춤을 추었어요. 크로노스가 아기 울음소리를 듣지 못하게 하려고요."},{"k":"p","t":"제우스는 동굴에서 튼튼하고 씩씩하게 자랐어요. 그리고 마침내 자기가 누구인지, 형과 누나들이 어디에 있는지 알게 되었지요. \"이제 내가 형과 누나들을 구하러 가겠어!\""}],"q":[{"q":"가이아가 건넨 커다란 낫을 들고 아버지에게 맞선 티탄은?","o":["오케아노스","히페리온","크로노스","아틀라스"],"a":2,"e":"막내 크로노스가 용감하게 나서서 우라노스에게 맞섰고, 새 왕이 되었어요."},{"q":"모든 것을 기억하는 기억의 여신은?","o":["므네모시네","테미스","레아","헤스티아"],"a":0,"e":"므네모시네는 기억의 여신이에요. 나중에 아홉 무사이의 엄마가 된답니다."},{"q":"크로노스가 아기들을 삼킨 까닭은?","o":["배가 고파서","아이에게 왕 자리를 빼앗길까 봐","아기들이 시끄러워서","가이아가 시켜서"],"a":1,"e":"가이아가 \"너도 네 아이에게 왕 자리를 빼앗길 것\"이라고 말해서 크로노스는 걱정이 되었어요."},{"q":"레아가 막내 아기 대신 크로노스에게 건넨 것은?","o":["사과","베개","포대기에 싼 돌","황금 공"],"a":2,"e":"레아는 돌을 포대기에 싸서 건넸고, 크로노스는 돌인 줄도 모르고 삼켰어요."},{"q":"아기 제우스가 숨어서 자란 곳은?","o":["크레타섬의 동굴","올림포스산","바닷속 궁전","타르타로스"],"a":0,"e":"제우스는 크레타섬 동굴에서 님프들과 염소의 보살핌을 받으며 자랐어요."}]},{"n":3,"t":"신들의 전쟁","sub":"젊은 신들과 티탄들이 세상을 두고 겨뤄요","b":[{"k":"img","i":0,"f":"images/scenes/c03-00.png","cap":"장 표지","who":["zeus","cronus","atlas","arges","briareus"]},{"k":"p","t":"다 자란 제우스는 형과 누나들을 구할 방법을 찾았어요. 혼자서는 힘센 아버지를 이길 수 없었으니까요."},{"k":"img","i":1,"f":"images/scenes/c03-01.png","cap":"형제들이 크로노스의 배 속에서 풀려나는 장면","who":["metis","cronus","hera","poseidon","hades","demeter","hestia"]},{"k":"who","id":"metis"},{"k":"p","t":"제우스를 도와준 것은 지혜로운 티탄 여신 메티스였어요. 메티스는 먹으면 배 속에 든 것을 모두 토해 내게 되는 신기한 약을 만들어 주었지요. 제우스는 이 약을 꿀물에 몰래 섞어 크로노스에게 건넸어요. 크로노스가 약을 꿀꺽 마시자, 배가 꾸르륵거리더니 가장 먼저 레아가 건넨 돌이 튀어나왔어요. 그리고 헤스티아, 데메테르, 헤라, 하데스, 포세이돈이 차례로 튀어나왔지요! 배 속에서 다 자란 형과 누나들은 막내 제우스를 끌어안고 기뻐했어요."},{"k":"who","id":"hera"},{"k":"who","id":"poseidon"},{"k":"who","id":"hades"},{"k":"p","t":"이제 제우스와 형제들은 크로노스와 티탄들에게 맞서기로 했어요. 젊은 신들은 올림포스산에, 티탄들은 오트리스산에 자리를 잡았지요. 이렇게 신들과 티탄들의 큰 전쟁이 시작되었어요."},{"k":"img","i":3,"f":"images/scenes/c03-03.png","cap":"신들과 티탄의 큰 전쟁","who":["zeus","cronus","briareus","cottus","gyges"]},{"k":"p","t":"전쟁은 무려 10년 동안이나 이어졌어요. 양쪽 모두 힘이 엄청나서 좀처럼 승부가 나지 않았지요. 그때 할머니 가이아가 제우스에게 귀띔해 주었어요. \"타르타로스에 갇힌 외눈 거인들과 팔 백 개 거인들을 풀어 주거라. 그들이 너를 도울 거란다.\""},{"k":"img","i":2,"f":"images/scenes/c03-02.png","cap":"키클롭스가 제우스에게 번개를 만들어 주는 장면","who":["arges","brontes","steropes","zeus"]},{"k":"who","id":"arges"},{"k":"who","id":"briareus"},{"k":"p","t":"제우스는 땅속 깊은 곳으로 내려가 거인들을 풀어 주었어요. 고마워한 외눈 거인 키클롭스 삼형제는 솜씨 좋은 대장장이였어요. 그들은 제우스에게 번쩍이는 번개를, 포세이돈에게 바다를 뒤흔드는 삼지창을, 하데스에게 쓰면 모습이 보이지 않는 투구를 만들어 주었지요. 팔 백 개 거인들은 백 개의 손으로 커다란 바위를 한꺼번에 던졌어요. 하늘에서는 번개가 번쩍이고, 바위가 비처럼 쏟아졌어요. 마침내 티탄들은 전쟁에서 지고 말았어요."},{"k":"img","i":4,"f":"images/scenes/c03-04.png","cap":"아틀라스가 하늘을 짊어지는 장면","who":["atlas"]},{"k":"who","id":"atlas"},{"k":"p","t":"진 티탄들은 타르타로스에 갇혔고, 팔 백 개 거인들이 그 문을 지켰어요. 티탄 가운데 가장 힘이 센 아틀라스는 특별한 벌을 받았어요. 세상의 서쪽 끝에 서서 무거운 하늘을 어깨로 영원히 떠받치게 된 거예요."},{"k":"img","i":5,"f":"images/scenes/c03-05.png","cap":"제우스와 거대한 티폰의 대결","who":["zeus","typhon"]},{"k":"who","id":"typhon"},{"k":"p","t":"그런데 가이아는 자기 아이들인 티탄들이 갇힌 것이 또 속상했어요. 그래서 가장 크고 무시무시한 괴물 티폰을 낳았지요. 티폰은 머리가 하늘의 별에 닿을 만큼 컸고, 어깨에는 뱀 머리가 백 개나 달려 있었어요. 티폰이 쳐들어오자 다른 신들은 깜짝 놀라 동물로 변해 이집트까지 달아났대요. 하지만 제우스는 물러서지 않았어요. 제우스는 번개를 던지고 또 던지며 끝까지 싸웠고, 마침내 티폰을 커다란 에트나산 아래에 눌러 가두었어요. 지금도 에트나 화산이 연기를 뿜는 건 티폰이 산 밑에서 씩씩거리기 때문이래요."},{"k":"p","t":"이제 세상은 제우스와 형제들의 것이 되었어요. 다음 장에서는 새로운 신들이 어떻게 세상을 나누고, 어떤 신들이 더 태어났는지 알아볼 거예요."}],"q":[{"q":"크로노스에게 약을 먹여 형과 누나들을 구하도록 도와준 지혜의 여신은?","o":["메티스","테미스","헤라","가이아"],"a":0,"e":"지혜로운 메티스가 먹으면 배 속의 것을 토해 내는 약을 만들어 주었어요."},{"q":"신들과 티탄들의 전쟁은 몇 년 동안 이어졌나요?","o":["1년","3년","10년","100년"],"a":2,"e":"전쟁은 무려 10년 동안 이어졌어요."},{"q":"외눈 거인 키클롭스가 제우스에게 만들어 준 것은?","o":["삼지창","번개","투구","방패"],"a":1,"e":"키클롭스는 제우스에게 번개, 포세이돈에게 삼지창, 하데스에게 투구를 만들어 주었어요."},{"q":"전쟁에 진 뒤 하늘을 어깨로 떠받치게 된 티탄은?","o":["크로노스","오케아노스","아틀라스","히페리온"],"a":2,"e":"가장 힘센 티탄 아틀라스는 세상 서쪽 끝에서 하늘을 떠받치게 되었어요."},{"q":"제우스가 티폰을 눌러 가둔 산은?","o":["올림포스산","에트나산","이다산","오트리스산"],"a":1,"e":"티폰은 에트나산 아래에 갇혔어요. 화산이 연기를 뿜는 건 티폰 때문이라고 옛사람들은 생각했대요."}]},{"n":4,"t":"올림포스의 신들","sub":"하늘·바다·저승을 나누고, 새로운 신들이 태어나요","b":[{"k":"img","i":0,"f":"images/scenes/c04-00.png","cap":"장 표지","who":["zeus","hera","poseidon","demeter","athena","apollo","artemis","ares","aphrodite","hephaestus","hermes","dionysus"]},{"k":"p","t":"전쟁이 끝나고 제우스와 형제들은 세상을 어떻게 다스릴지 의논했어요."},{"k":"img","i":1,"f":"images/scenes/c04-01.png","cap":"세 형제가 제비뽑기로 하늘·바다·저승을 나누는 장면","who":["zeus","poseidon","hades"]},{"k":"who","id":"zeus"},{"k":"p","t":"세 형제 제우스, 포세이돈, 하데스는 투구에 제비를 넣고 하나씩 뽑았어요. 제우스는 하늘을, 포세이돈은 바다를, 하데스는 땅속 저승을 뽑았지요. 넓은 땅과 높은 올림포스산은 모두가 함께 쓰기로 했어요."},{"k":"who","id":"poseidon"},{"k":"who","id":"hades"},{"k":"p","t":"포세이돈은 바닷속 깊은 곳에 반짝이는 궁전을 짓고, 삼지창으로 파도를 일으키거나 잠재웠어요. 하데스는 세상을 떠난 사람들이 가는 저승의 왕이 되었어요. 하데스는 무섭게 보일 때도 있지만, 사실은 공평하고 규칙을 잘 지키는 신이었대요."},{"k":"who","id":"hera"},{"k":"who","id":"demeter"},{"k":"who","id":"hestia"},{"k":"p","t":"제우스는 신들의 왕이 되어 누나 헤라와 결혼했어요. 헤라는 신들의 여왕이 되어 결혼과 가족을 지켰지요. 데메테르는 곡식과 농사를 맡아 들판을 황금빛으로 물들였고, 헤스티아는 집집마다 있는 따뜻한 화덕의 불을 지켰어요."},{"k":"img","i":2,"f":"images/scenes/c04-02.png","cap":"제우스의 머리에서 아테나가 태어나는 장면","who":["zeus","hephaestus","athena"]},{"k":"who","id":"athena"},{"k":"p","t":"그런데 어느 날, 제우스가 머리가 깨질 듯이 아프다며 소리를 질렀어요. 대장장이 신 헤파이스토스가 작은 망치로 제우스의 머리를 톡 두드리자, 번쩍하는 금빛과 함께 무언가가 튀어나왔어요. 갑옷을 입고 창과 방패를 든 여신, 아테나였어요! 아테나는 엄마 메티스를 닮아 지혜로웠고, 전쟁에서 나라를 지키는 법도 잘 알았어요."},{"k":"img","i":3,"f":"images/scenes/c04-03.png","cap":"바다 거품에서 아프로디테가 태어나는 장면","who":["aphrodite"]},{"k":"who","id":"aphrodite"},{"k":"p","t":"바다에서는 하얀 거품 속에서 아름다운 여신이 태어났어요. 커다란 조개껍데기를 타고 바닷가로 온 이 여신이 사랑과 아름다움의 여신 아프로디테예요. 아프로디테가 걸어가는 곳마다 꽃이 피어났대요."},{"k":"who","id":"apollo"},{"k":"who","id":"artemis"},{"k":"who","id":"ares"},{"k":"who","id":"hephaestus"},{"k":"p","t":"올림포스에는 제우스의 아이들이 하나둘 늘어났어요. 레토가 낳은 쌍둥이 아폴론과 아르테미스도 있었지요. 아폴론은 빛과 음악의 신으로 리라를 켜고 활을 쏘았고, 아르테미스는 사냥과 달의 여신으로 숲속 동물들을 지켰어요. 헤라가 낳은 아레스는 전쟁의 신이었고, 헤파이스토스는 불과 대장간의 신이었어요. 헤파이스토스는 신들의 궁전과 무기와 멋진 물건들을 뚝딱뚝딱 만들어 냈지요."},{"k":"img","i":4,"f":"images/scenes/c04-04.png","cap":"아기 헤르메스가 소 떼를 훔치는 장면","who":["hermes","apollo"]},{"k":"who","id":"hermes"},{"k":"p","t":"마이아가 낳은 헤르메스는 태어나자마자 장난꾸러기였어요. 태어난 바로 그날 요람에서 몰래 빠져나와 형 아폴론의 소 떼를 훔쳤거든요! 헤르메스는 소들을 뒤로 걷게 해서 발자국을 헷갈리게 만들었어요. 들킨 뒤에는 거북이 등딱지로 만든 악기 리라를 아폴론에게 선물해서 화해했지요. 헤르메스는 날개 달린 신발을 신고 신들의 심부름을 하는 전령의 신이 되었어요."},{"k":"who","id":"dionysus"},{"k":"p","t":"제우스와 사람 공주 세멜레 사이에서 태어난 디오니소스는 포도와 포도주, 즐거운 잔치의 신이 되었어요."},{"k":"img","i":5,"f":"images/scenes/c04-05.png","cap":"아테나와 포세이돈의 아테네 선물 대결","who":["athena","poseidon"]},{"k":"p","t":"이 무렵 그리스의 한 도시를 두고 아테나와 포세이돈이 다툰 일이 있었어요. 두 신은 도시 사람들에게 선물을 하나씩 주고, 더 좋은 선물을 준 신이 도시의 수호신이 되기로 했지요. 포세이돈은 삼지창으로 바위를 내리쳐 샘물이 솟게 했는데, 맛을 보니 짠 바닷물이었어요. 아테나는 땅에 올리브 나무를 심었어요. 올리브는 열매도 먹고, 기름도 짜고, 나무로 물건도 만들 수 있었지요. 사람들은 아테나의 선물을 골랐고, 도시의 이름은 아테나를 따서 아테네가 되었어요."},{"k":"p","t":"이렇게 올림포스의 열두 신이 모두 모였어요. 그런데 이 세상에는 아직 사람이 없었어요. 다음 장에서는 사람이 어떻게 생겨났는지 들려줄게요."}],"q":[{"q":"제비뽑기에서 바다를 뽑은 신은?","o":["제우스","포세이돈","하데스","헤르메스"],"a":1,"e":"제우스는 하늘, 포세이돈은 바다, 하데스는 저승을 뽑았어요."},{"q":"제우스의 머리에서 갑옷을 입고 태어난 여신은?","o":["아프로디테","아르테미스","아테나","헤라"],"a":2,"e":"헤파이스토스가 망치로 톡 두드리자 아테나가 갑옷을 입고 튀어나왔어요."},{"q":"아기 헤르메스가 형 아폴론에게서 훔친 것은?","o":["리라","활","소 떼","황금 사과"],"a":2,"e":"헤르메스는 소들을 뒤로 걷게 해서 발자국을 헷갈리게 했어요."},{"q":"아테나가 도시 사람들에게 준 선물은?","o":["올리브 나무","샘물","황금","말"],"a":0,"e":"올리브 나무를 선물한 아테나가 이겨서 도시 이름이 아테네가 되었어요."},{"q":"바다 거품에서 태어난 사랑과 아름다움의 여신은?","o":["헤스티아","데메테르","아프로디테","아르테미스"],"a":2,"e":"아프로디테는 조개껍데기를 타고 바닷가로 왔어요."}]},{"n":5,"t":"사람의 탄생","sub":"진흙으로 빚은 사람과 훔쳐 온 불, 그리고 판도라","b":[{"k":"img","i":0,"f":"images/scenes/c05-00.png","cap":"장 표지","who":["prometheus","epimetheus","pandora"]},{"k":"who","id":"prometheus"},{"k":"who","id":"epimetheus"},{"k":"p","t":"티탄들 가운데에는 전쟁에서 제우스 편을 든 형제가 있었어요. 앞일을 미리 생각하는 프로메테우스와, 일을 저지르고 나서야 생각하는 동생 에피메테우스예요. 이름부터 '먼저 생각하는 자', '나중에 생각하는 자'라는 뜻이래요."},{"k":"img","i":1,"f":"images/scenes/c05-01.png","cap":"프로메테우스가 진흙으로 사람을 빚는 장면","who":["prometheus","athena"]},{"k":"p","t":"어느 날 신들은 두 형제에게 땅 위에 살 생명들을 만들라는 일을 맡겼어요. 프로메테우스는 강가의 진흙을 빚어 신들을 닮은 모습으로 사람을 만들었어요. 다른 동물들처럼 네 발로 기지 않고, 두 발로 서서 하늘을 올려다볼 수 있게요. 지혜의 여신 아테나가 그 진흙 인형에 숨결을 불어넣자, 사람들이 눈을 깜빡이며 살아났대요."},{"k":"p","t":"동물들에게 좋은 것을 나눠 주는 일은 에피메테우스가 맡았어요. 에피메테우스는 신이 나서 사자에게는 날카로운 이빨을, 새에게는 날개를, 곰에게는 두툼한 털을, 거북에게는 단단한 등딱지를 나눠 주었어요. 그런데 사람 차례가 되자 남은 것이 하나도 없었어요! 사람은 털도 없고, 날개도 없고, 이빨도 약했지요. 사람들은 추위에 떨고, 날고기를 먹으며 힘들게 살았어요."},{"k":"img","i":2,"f":"images/scenes/c05-02.png","cap":"회향 줄기에 불씨를 숨겨 오는 장면","who":["prometheus"]},{"k":"p","t":"프로메테우스는 사람들이 불쌍했어요. \"사람들에게 불이 있다면 따뜻하게 지내고, 음식을 익혀 먹고, 도구도 만들 수 있을 텐데.\" 하지만 제우스는 불을 사람들에게 주지 말라고 했어요. 프로메테우스는 속이 빈 회향 줄기를 들고 몰래 하늘로 올라갔어요. 그리고 태양 마차의 불씨를 줄기 속에 숨겨 땅으로 가져왔지요. 사람들은 처음으로 불을 갖게 되었어요."},{"k":"who","id":"caucasian_eagle"},{"k":"p","t":"제우스는 크게 화가 났어요. 제우스는 프로메테우스를 카우카소스산의 바위에 사슬로 묶어 두고, 날마다 커다란 독수리가 찾아와 괴롭히게 했어요. 이 벌은 아주 오랜 세월이 흐른 뒤, 영웅 헤라클레스가 찾아와 독수리를 쫓아내고 사슬을 풀어 줄 때까지 이어졌어요."},{"k":"img","i":3,"f":"images/scenes/c05-03.png","cap":"판도라가 항아리를 여는 장면","who":["pandora","epimetheus"]},{"k":"who","id":"pandora"},{"k":"p","t":"제우스는 사람들에게도 벌을 주기로 했어요. 제우스는 헤파이스토스에게 진흙으로 아름다운 여자를 만들게 했어요. 신들은 저마다 선물을 하나씩 주었지요. 아프로디테는 아름다움을, 아테나는 베 짜는 솜씨를, 헤르메스는 말솜씨와 호기심을 주었어요. 그래서 이 여자의 이름은 '모든 선물을 받은 자'라는 뜻의 판도라가 되었어요."},{"k":"p","t":"프로메테우스는 동생에게 \"제우스가 주는 선물은 절대 받지 마라\"라고 당부했어요. 하지만 에피메테우스는 판도라를 보자마자 반해서 결혼해 버렸어요. 판도라는 신들이 준 커다란 항아리를 가지고 왔어요. \"절대 열어 보면 안 된다\"는 말과 함께요. 하지만 판도라는 궁금해서 견딜 수 없었어요. 어느 날 판도라는 살짝, 아주 살짝 뚜껑을 열었어요."},{"k":"p","t":"그러자 항아리 속에서 병, 걱정, 슬픔, 다툼 같은 나쁜 것들이 회색 구름처럼 우르르 쏟아져 나왔어요! 깜짝 놀란 판도라가 얼른 뚜껑을 닫았을 때, 항아리 바닥에는 딱 하나가 남아 있었어요. 바로 '희망'이었지요. 그래서 사람들은 힘든 일이 있어도 희망을 품고 살아갈 수 있게 되었대요."},{"k":"img","i":4,"f":"images/scenes/c05-04.png","cap":"대홍수 위의 작은 방주","who":["deucalion","pyrrha"]},{"k":"who","id":"deucalion"},{"k":"who","id":"pyrrha"},{"k":"p","t":"시간이 흘러 사람들은 점점 거칠고 못되게 변했어요. 제우스는 세상을 새로 시작하려고 큰 홍수를 일으키기로 했어요. 이 사실을 미리 안 프로메테우스는 아들 데우칼리온에게 몰래 알려 주었어요. \"튼튼한 방주를 만들어라.\" 데우칼리온은 아내 피라와 함께 커다란 나무 상자 배를 만들어 먹을 것을 싣고 올라탔어요. 에피메테우스와 판도라의 딸인 피라는 마음씨가 착한 사람이었지요."},{"k":"p","t":"아홉 날 낮과 밤 동안 비가 쏟아져 온 세상이 물에 잠겼어요. 방주는 물 위를 둥둥 떠다니다가 마침내 파르나소스산 꼭대기에 닿았어요."},{"k":"img","i":5,"f":"images/scenes/c05-05.png","cap":"어깨 너머로 돌을 던지는 장면","who":["deucalion","pyrrha"]},{"k":"p","t":"물이 빠지자 세상에는 두 사람만 남아 있었어요. 둘은 너무 외로워서 테미스 여신의 신전에 가서 기도했어요. 그러자 이런 대답이 들려왔어요. \"너희 어머니의 뼈를 어깨 너머로 던져라.\" 두 사람은 한참 고민하다가 깨달았어요. 어머니는 대지 가이아이고, 어머니의 뼈는 땅 위의 돌이라는 걸요! 데우칼리온이 던진 돌은 남자가, 피라가 던진 돌은 여자가 되었어요. 이렇게 세상에 다시 사람들이 가득해졌답니다."}],"q":[{"q":"강가의 진흙으로 사람을 빚은 티탄은?","o":["에피메테우스","프로메테우스","아틀라스","크로노스"],"a":1,"e":"프로메테우스는 두 발로 서서 하늘을 볼 수 있는 모습으로 사람을 만들었어요."},{"q":"프로메테우스가 불씨를 숨겨 온 것은?","o":["항아리","방패","회향 줄기","조개껍데기"],"a":2,"e":"속이 빈 회향 줄기에 불씨를 숨겨 땅으로 가져왔어요."},{"q":"판도라의 항아리 맨 밑에 남은 것은?","o":["희망","황금","사랑","불씨"],"a":0,"e":"나쁜 것들이 모두 나간 뒤 항아리 바닥에는 희망이 남았어요."},{"q":"대홍수 때 방주를 타고 살아남은 부부는?","o":["에피메테우스와 판도라","제우스와 헤라","데우칼리온과 피라","크로노스와 레아"],"a":2,"e":"프로메테우스의 아들 데우칼리온과 아내 피라가 방주를 타고 살아남았어요."},{"q":"데우칼리온과 피라가 어깨 너머로 던져 사람이 된 것은?","o":["씨앗","돌","조개","꽃"],"a":1,"e":"'어머니의 뼈'는 대지 가이아의 돌이었어요. 던진 돌이 사람이 되었지요."}]},{"n":6,"t":"신들을 만난 사람들","sub":"신들과 얽힌 신기하고 놀라운 이야기들","b":[{"k":"img","i":0,"f":"images/scenes/c06-00.png","cap":"장 표지","who":["persephone","arachne","narcissus","midas","phaethon"]},{"k":"p","t":"세상에 사람들이 다시 가득해지자, 신들은 자주 땅으로 내려와 사람들과 만났어요. 그때마다 신기하고 놀라운 일들이 일어났지요. 이번 장에서는 그런 이야기들을 하나씩 들려줄게요."},{"k":"img","i":1,"f":"images/scenes/c06-01.png","cap":"꽃밭의 페르세포네와 석류","who":["persephone","hades"]},{"k":"who","id":"persephone"},{"k":"who","id":"demeter"},{"k":"p","t":"곡식의 여신 데메테르에게는 페르세포네라는 사랑스러운 딸이 있었어요. 어느 봄날 페르세포네가 들판에서 꽃을 꺾고 있을 때였어요. 갑자기 땅이 쩍 갈라지더니 검은 말이 끄는 마차가 튀어나왔어요. 저승의 왕 하데스가 페르세포네를 아내로 삼으려고 저승으로 데려간 거예요."},{"k":"p","t":"딸을 잃은 데메테르는 횃불을 들고 온 세상을 헤매며 딸을 찾았어요. 데메테르가 슬퍼하는 동안 들판의 곡식은 자라지 않았고, 나무에는 열매가 맺히지 않았어요. 사람들이 굶주리자 제우스는 헤르메스를 저승으로 보내 페르세포네를 데려오게 했어요."},{"k":"p","t":"그런데 페르세포네는 저승을 떠나기 전 석류 몇 알을 먹었어요. 저승의 음식을 먹은 사람은 저승을 완전히 떠날 수 없다는 규칙이 있었지요. 그래서 페르세포네는 한 해의 몇 달은 저승에서 하데스와, 나머지는 땅 위에서 엄마와 지내게 되었어요. 딸이 돌아오면 데메테르가 기뻐해서 봄과 여름이 오고, 딸이 저승으로 가면 슬퍼해서 가을과 겨울이 온대요. 이것이 계절이 생긴 이야기예요."},{"k":"img","i":2,"f":"images/scenes/c06-02.png","cap":"아라크네와 아테나의 베 짜기 대결","who":["arachne","athena"]},{"k":"who","id":"arachne"},{"k":"p","t":"리디아에는 베 짜는 솜씨가 누구보다 뛰어난 아라크네라는 소녀가 있었어요. 사람들이 칭찬하자 아라크네는 \"나는 아테나 여신보다 더 잘 짜요!\"라고 뽐냈어요. 할머니로 변장한 아테나가 찾아와 겸손해지라고 타일렀지만, 아라크네는 듣지 않았어요. 결국 둘은 베 짜기 대결을 벌였어요. 아라크네의 솜씨는 정말 흠잡을 데가 없었지만, 신들을 놀리는 그림을 짜 넣었어요. 화가 난 아테나는 아라크네를 거미로 바꾸었어요. 그래서 거미는 지금도 쉬지 않고 실을 뽑아 줄을 짜는 거래요."},{"k":"img","i":3,"f":"images/scenes/c06-03.png","cap":"샘물을 들여다보는 나르키소스와 숨어 있는 에코","who":["narcissus","echo"]},{"k":"who","id":"narcissus"},{"k":"who","id":"echo"},{"k":"p","t":"숲에는 말을 잘하는 요정 에코가 살았어요. 하지만 수다로 헤라를 속인 벌로, 남이 한 말의 끝부분만 따라 할 수 있게 되었지요. 에코는 잘생긴 청년 나르키소스를 좋아했지만, 먼저 말을 걸 수가 없었어요. 나르키소스는 에코를 차갑게 밀어냈고, 에코는 슬퍼하다가 목소리만 남게 되었어요. 그래서 산에서 \"야호!\" 하고 외치면 에코가 \"야호!\" 하고 대답하는 거래요."},{"k":"p","t":"다른 사람의 마음을 무시한 나르키소스는 벌을 받았어요. 맑은 샘물을 들여다보다가 물에 비친 자기 얼굴에 반해 버린 거예요. 나르키소스는 그 자리를 떠나지 못했고, 그가 있던 자리에는 하얀 수선화 한 송이가 피어났대요."},{"k":"img","i":4,"f":"images/scenes/c06-04.png","cap":"황금으로 변한 음식을 든 미다스","who":["midas","silenus"]},{"k":"who","id":"midas"},{"k":"who","id":"silenus"},{"k":"p","t":"프리기아의 미다스 왕은 길 잃은 디오니소스의 스승 실레노스를 정성껏 대접해 주었어요. 기뻐한 디오니소스가 소원을 하나 들어주겠다고 하자, 미다스는 \"내가 만지는 것은 모두 황금이 되게 해 주세요!\"라고 빌었어요. 처음에는 신이 났지요. 나뭇가지도, 돌멩이도 만지는 대로 황금이 되었으니까요. 하지만 빵을 집어도 황금, 포도를 집어도 황금이 되어 아무것도 먹을 수 없었어요. 미다스는 울며 소원을 거둬 달라고 빌었고, 팍톨로스강에서 몸을 씻고서야 원래대로 돌아왔어요."},{"k":"img","i":5,"f":"images/scenes/c06-05.png","cap":"태양 마차를 몰다 흔들리는 파에톤","who":["phaethon","helios"]},{"k":"who","id":"phaethon"},{"k":"who","id":"helios"},{"k":"p","t":"태양신 헬리오스에게는 파에톤이라는 아들이 있었어요. 친구들이 \"네가 태양신의 아들이라는 증거를 대 봐!\" 하고 놀리자, 파에톤은 아버지를 찾아가 소원을 들어 달라고 했어요. 헬리오스는 스틱스강에 걸고 무엇이든 들어주겠다고 약속했어요. 그런데 파에톤의 소원은 하루 동안 태양 마차를 모는 것이었어요!"},{"k":"p","t":"헬리오스는 말렸지만 약속을 물릴 수 없었어요. 파에톤이 마차에 올라타자, 불을 뿜는 말들은 주인이 아닌 걸 알고 제멋대로 날뛰었어요. 마차가 너무 높이 올라가자 땅이 꽁꽁 얼었고, 너무 낮게 내려오자 땅이 뜨겁게 타올랐지요. 세상이 위험해지자 제우스는 번개로 마차를 멈추게 했고, 파에톤은 에리다노스강으로 떨어졌어요. 파에톤의 누나들은 너무 슬프게 울다가 강가의 포플러 나무가 되었고, 그 눈물은 노란 호박 보석이 되었대요."}],"q":[{"q":"페르세포네가 저승에서 먹어 땅 위로 완전히 돌아올 수 없게 된 과일은?","o":["사과","포도","석류","무화과"],"a":2,"e":"저승의 음식인 석류를 먹어서, 한 해의 몇 달은 저승에서 지내게 되었어요."},{"q":"페르세포네 이야기는 무엇이 생긴 까닭을 알려 주나요?","o":["밤과 낮","계절","무지개","바다"],"a":1,"e":"딸이 돌아오면 봄과 여름, 떠나면 가을과 겨울이 온대요."},{"q":"아테나와 베 짜기 대결을 한 뒤 거미가 된 소녀는?","o":["아라크네","에코","판도라","페르세포네"],"a":0,"e":"아라크네는 거미가 되어 지금도 실을 뽑아 줄을 짠대요."},{"q":"남이 한 말의 끝부분만 따라 할 수 있게 된 요정은?","o":["에코","님프","이리스","닉스"],"a":0,"e":"메아리를 영어로 '에코'라고 하는 것도 이 요정에게서 왔어요."},{"q":"만지는 것마다 황금이 되게 해 달라고 빈 왕은?","o":["미노스","미다스","아이게우스","크로노스"],"a":1,"e":"미다스는 음식까지 황금이 되어 먹을 수 없게 되자 소원을 거둬 달라고 빌었어요."}]},{"n":7,"t":"사랑과 노래","sub":"프시케의 모험과 오르페우스의 노래","b":[{"k":"img","i":0,"f":"images/scenes/c07-00.png","cap":"장 표지","who":["eros","psyche","orpheus","eurydice"]},{"k":"p","t":"사랑은 때때로 아주 큰 용기를 내게 만들어요. 이번 장에서는 사랑하는 사람을 위해 먼 길을 떠난 두 사람의 이야기를 들려줄게요."},{"k":"who","id":"psyche"},{"k":"p","t":"어느 나라에 프시케라는 공주가 살았어요. 프시케가 얼마나 아름다웠는지, 사람들은 아프로디테 여신의 신전에 가지 않고 프시케를 보러 몰려들었어요. 질투가 난 아프로디테는 아들 에로스를 불렀어요. \"저 아이가 세상에서 가장 못난 사람을 사랑하게 만들어라.\""},{"k":"who","id":"eros"},{"k":"p","t":"하지만 에로스는 프시케를 보자마자 그만 자기가 쏜 사랑의 화살에 손을 찔리고 말았어요. 에로스가 프시케를 사랑하게 된 거예요! 에로스는 바람의 신 제피로스를 시켜 프시케를 꽃이 가득한 궁전으로 데려왔어요. 밤마다 에로스가 찾아와 다정하게 이야기를 나누었지만, 딱 한 가지 약속이 있었어요. \"절대로 내 얼굴을 보려고 하지 마세요.\""},{"k":"img","i":1,"f":"images/scenes/c07-01.png","cap":"등불을 들고 잠든 에로스를 보는 프시케","who":["psyche","eros"]},{"k":"p","t":"프시케는 행복했지만, 언니들이 \"네 남편은 무서운 괴물일지도 몰라!\" 하고 겁을 주자 궁금해졌어요. 어느 밤 프시케는 몰래 등불을 들고 잠든 남편의 얼굴을 비춰 보았어요. 그곳에는 괴물이 아니라 날개 달린 아름다운 신 에로스가 잠들어 있었지요. 깜짝 놀란 프시케의 손이 떨리면서 뜨거운 기름 한 방울이 에로스의 어깨에 떨어졌어요. 잠에서 깬 에로스는 슬픈 얼굴로 \"믿음이 없는 곳에는 사랑이 머물 수 없어요\"라고 말하고는 날아가 버렸어요."},{"k":"img","i":2,"f":"images/scenes/c07-02.png","cap":"개미들이 곡식을 나눠 주는 장면","who":["psyche"]},{"k":"p","t":"프시케는 에로스를 다시 만나려고 아프로디테를 찾아갔어요. 아프로디테는 아주 어려운 일들을 시켰어요. 첫 번째 일은 산더미처럼 뒤섞인 보리, 콩, 좁쌀을 하룻밤 사이에 종류별로 나누는 것이었어요. 프시케가 울고 있을 때, 개미들이 줄지어 나타나 곡식을 한 알 한 알 날라 깔끔하게 나눠 주었어요. 다른 어려운 일들도 강가의 갈대와 독수리가 도와주었지요. 마지막으로 프시케는 저승까지 내려가 페르세포네에게서 아름다움이 담긴 상자를 받아 왔어요."},{"k":"p","t":"그 모습을 본 에로스는 프시케를 용서하고 다시 찾아왔어요. 제우스는 프시케에게 신들의 음식 암브로시아를 주어 신이 되게 했어요. 프시케는 나비 날개를 단 영혼의 여신이 되어 에로스와 영원히 함께 살았대요."},{"k":"who","id":"orpheus"},{"k":"who","id":"calliope"},{"k":"p","t":"트라키아에는 오르페우스라는 음악가가 살았어요. 엄마는 아홉 무사이의 맏이 칼리오페였고, 아폴론에게서 황금 리라를 받았지요. 오르페우스가 리라를 켜며 노래하면 새들이 날아와 앉고, 사나운 짐승들이 순해지고, 나무와 바위까지 가까이 다가왔대요."},{"k":"who","id":"eurydice"},{"k":"p","t":"오르페우스는 요정 에우리디케와 결혼했어요. 그런데 결혼한 지 얼마 되지 않아, 에우리디케가 풀밭을 걷다가 뱀에게 발목을 물려 세상을 떠나고 말았어요. 오르페우스는 너무 슬퍼서 노래를 부를 수가 없었어요. 그리고 결심했지요. \"저승에 가서 에우리디케를 데려오겠어!\""},{"k":"img","i":3,"f":"images/scenes/c07-03.png","cap":"저승에서 리라를 켜는 오르페우스","who":["orpheus","hades","persephone"]},{"k":"p","t":"오르페우스는 리라를 들고 저승으로 내려갔어요. 뱃사공 카론도, 머리 셋 달린 개 케르베로스도 오르페우스의 노래를 듣고 길을 비켜 주었어요. 마침내 저승의 왕 하데스와 왕비 페르세포네 앞에 선 오르페우스는 슬프고 아름다운 노래를 불렀어요. 차갑던 저승이 온통 눈물바다가 되었지요. 하데스는 말했어요. \"에우리디케를 데려가도 좋다. 단, 땅 위에 다 나갈 때까지 절대로 뒤를 돌아보면 안 된다.\""},{"k":"img","i":4,"f":"images/scenes/c07-04.png","cap":"출구 앞에서 뒤돌아보는 순간","who":["orpheus","eurydice"]},{"k":"p","t":"오르페우스는 어두운 길을 걷고 또 걸었어요. 뒤에서는 아무 소리도 들리지 않았어요. '에우리디케가 정말 따라오고 있을까?' 출구의 환한 빛이 보이는 순간, 오르페우스는 참지 못하고 뒤를 돌아보았어요. 에우리디케는 바로 뒤에 있었지만, 안개처럼 희미해지며 다시 저승으로 사라졌어요. 오르페우스는 그 뒤로 평생 에우리디케를 그리워하며 슬픈 노래를 불렀대요. 오르페우스의 리라는 하늘로 올라가 거문고자리가 되었어요."},{"k":"img","i":5,"f":"images/scenes/c07-05.png","cap":"조각상이 사람이 되는 장면","who":["pygmalion","aphrodite"]},{"k":"who","id":"pygmalion"},{"k":"p","t":"사랑 이야기가 늘 슬픈 것만은 아니에요. 키프로스섬의 조각가 피그말리온은 하얀 상아로 세상에서 가장 아름다운 여인의 조각상을 만들었어요. 그리고 그 조각상을 진심으로 사랑하게 되었지요. 아프로디테의 축제 날, 피그말리온은 \"저 조각상 같은 아내를 만나게 해 주세요\"라고 기도했어요. 집에 돌아와 조각상의 손을 잡자, 차가운 상아가 점점 따뜻해지더니 볼이 발그레해지고 눈을 떴어요! 아프로디테가 소원을 들어준 거예요. 두 사람은 결혼해 행복하게 살았대요."}],"q":[{"q":"에로스가 프시케에게 한 단 한 가지 약속은?","o":["궁전 밖에 나가지 않기","자기 얼굴을 보려고 하지 않기","노래 부르지 않기","언니들을 만나지 않기"],"a":1,"e":"프시케가 등불로 얼굴을 비춰 보는 바람에 에로스는 날아가 버렸어요."},{"q":"뒤섞인 곡식을 나누는 일을 도와준 동물은?","o":["새","개미","거미","벌"],"a":1,"e":"개미들이 곡식을 한 알 한 알 날라 종류별로 나눠 주었어요."},{"q":"오르페우스의 엄마는 누구인가요?","o":["칼리오페","아프로디테","페르세포네","헤라"],"a":0,"e":"오르페우스의 엄마는 아홉 무사이의 맏이 칼리오페예요."},{"q":"하데스가 오르페우스에게 한 약속의 조건은?","o":["노래를 멈추지 않기","땅 위에 나갈 때까지 뒤돌아보지 않기","리라를 두고 가기","말을 하지 않기"],"a":1,"e":"출구 앞에서 뒤를 돌아보는 바람에 에우리디케는 다시 저승으로 사라졌어요."},{"q":"피그말리온이 만든 조각상은 어떻게 되었나요?","o":["하늘의 별이 되었어요","사람이 되었어요","황금이 되었어요","새가 되었어요"],"a":1,"e":"아프로디테가 기도를 들어주어 조각상이 사람이 되었어요."}]},{"n":8,"t":"페르세우스와 날개 달린 말","sub":"메두사를 물리친 영웅과 하늘을 나는 말","b":[{"k":"img","i":0,"f":"images/scenes/c08-00.png","cap":"장 표지","who":["perseus","pegasus","andromeda"]},{"k":"p","t":"이제부터는 영웅들의 시대예요. 신들의 도움을 받아 괴물을 물리치고 모험을 떠난 용감한 사람들의 이야기지요. 가장 먼저 만날 영웅은 페르세우스예요."},{"k":"img","i":1,"f":"images/scenes/c08-01.png","cap":"황금 비가 내리는 청동 탑","who":["danae"]},{"k":"who","id":"acrisius"},{"k":"who","id":"danae"},{"k":"p","t":"아르고스의 왕 아크리시오스에게는 다나에라는 딸이 있었어요. 어느 날 왕은 무서운 예언을 들었어요. \"왕의 손자가 왕을 해치게 될 것이다.\" 겁이 난 왕은 다나에를 높은 청동 탑에 가두고 아무도 만나지 못하게 했어요."},{"k":"p","t":"하지만 신들의 왕 제우스는 다나에를 보고 사랑하게 되었어요. 제우스는 반짝이는 황금 비로 변해 탑의 창문으로 스며들었지요. 얼마 뒤 다나에는 아기를 낳았어요. 그 아기가 페르세우스예요."},{"k":"img","i":2,"f":"images/scenes/c08-02.png","cap":"아기와 함께 상자에 실려 바다를 떠도는 다나에","who":["danae","perseus","acrisius"]},{"k":"who","id":"perseus"},{"k":"p","t":"아기 울음소리를 들은 왕은 깜짝 놀랐어요. 왕은 다나에와 아기 페르세우스를 나무 상자에 넣어 바다에 띄워 보냈어요. 상자는 파도를 타고 둥둥 떠다니다가 세리포스섬에 닿았고, 착한 어부 딕티스가 두 사람을 구해 주었어요. 페르세우스는 그 섬에서 씩씩한 청년으로 자랐어요."},{"k":"who","id":"polydectes"},{"k":"p","t":"그런데 섬의 왕 폴리덱테스가 다나에와 억지로 결혼하려고 했어요. 페르세우스가 방해가 되자, 왕은 꾀를 냈어요. \"네가 정말 용감하다면 메두사의 머리를 가져와 보거라.\" 메두사는 머리카락이 뱀이고, 눈을 마주치는 사람을 돌로 만들어 버리는 괴물이었어요. 아무도 살아 돌아오지 못한 위험한 일이었지요."},{"k":"who","id":"athena"},{"k":"who","id":"hermes"},{"k":"p","t":"다행히 신들이 페르세우스를 도와주었어요. 아테나는 거울처럼 반짝이는 방패를, 헤르메스는 무엇이든 자를 수 있는 굽은 칼을 빌려주었어요. \"먼저 그라이아이 세 자매를 찾아가거라. 그들이 길을 알고 있단다.\""},{"k":"img","i":3,"f":"images/scenes/c08-03.png","cap":"그라이아이의 눈을 가로채는 장면","who":["perseus","graiai"]},{"k":"who","id":"graiai"},{"k":"p","t":"그라이아이는 태어날 때부터 할머니였던 세 자매였어요. 셋이서 눈 하나와 이 하나를 나눠 쓰며 차례로 돌려 가며 보았지요. 페르세우스는 몰래 다가가, 한 자매가 다른 자매에게 눈을 건네주는 순간 휙 낚아챘어요. \"눈을 돌려받고 싶으면 요정들이 있는 곳을 알려 주세요!\" 그라이아이는 할 수 없이 길을 알려 주었어요. 페르세우스는 요정들에게서 하늘을 나는 날개 달린 신발, 쓰면 모습이 보이지 않는 투구, 튼튼한 자루를 얻었어요."},{"k":"img","i":4,"f":"images/scenes/c08-04.png","cap":"방패 거울로 메두사를 보는 장면","who":["perseus","medusa"]},{"k":"who","id":"medusa"},{"k":"p","t":"날개 신발을 신은 페르세우스는 세상 끝 고르곤 자매의 섬으로 날아갔어요. 섬에는 돌이 된 사람과 동물들이 가득했어요. 페르세우스는 메두사를 절대 똑바로 보지 않고, 아테나의 방패에 비친 모습만 보면서 뒷걸음질로 다가갔어요. 그리고 잠든 메두사를 물리친 뒤, 그 머리를 얼른 자루에 넣었지요."},{"k":"who","id":"pegasus"},{"k":"p","t":"그때 신기한 일이 일어났어요. 메두사에게서 하얀 날개가 달린 말 페가소스가 태어나 하늘로 날아오른 거예요."},{"k":"img","i":5,"f":"images/scenes/c08-05.png","cap":"안드로메다 구출","who":["perseus","andromeda","cetus"]},{"k":"who","id":"andromeda"},{"k":"who","id":"cetus"},{"k":"p","t":"집으로 돌아가던 페르세우스는 바닷가 바위에 사슬로 묶인 공주를 보았어요. 에티오피아의 공주 안드로메다였어요. 왕비 카시오페이아가 \"내 딸이 바다 요정들보다 아름답다\"고 뽐내는 바람에, 화가 난 포세이돈이 바다 괴물 케토스를 보냈거든요. 괴물을 달래려면 공주를 바쳐야 했지요. 바다가 부글부글 끓더니 괴물이 나타났어요. 페르세우스는 날개 신발로 날아올라 괴물과 싸워 물리쳤어요. 그리고 안드로메다와 결혼했어요."},{"k":"p","t":"세리포스섬으로 돌아온 페르세우스는 못된 폴리덱테스 왕에게 메두사의 머리를 보여 주었어요. 왕과 신하들은 그대로 돌이 되었지요. 페르세우스는 빌린 물건들을 신들에게 돌려주었고, 메두사의 머리는 아테나에게 바쳤어요. 아테나는 그것을 방패 한가운데 붙였대요. 그리고 오래전 예언은 끝내 이루어졌어요. 운동 경기에서 페르세우스가 던진 원반이 바람에 휘어 구경하던 할아버지 아크리시오스에게 맞고 만 거예요."},{"k":"img","i":6,"f":"images/scenes/c08-06.png","cap":"황금 굴레로 페가소스를 길들이는 벨레로폰","who":["bellerophon","pegasus","athena"]},{"k":"who","id":"bellerophon"},{"k":"p","t":"시간이 흘러, 코린토스에 벨레로폰이라는 젊은 영웅이 있었어요. 벨레로폰은 하늘을 나는 말 페가소스를 타 보는 게 꿈이었어요. 하지만 페가소스는 아무도 가까이 오지 못하게 했지요. 벨레로폰이 아테나의 신전에서 잠이 들자, 꿈에 아테나가 나타나 황금 굴레를 건네주었어요. 눈을 떠 보니 정말 머리맡에 황금 굴레가 있었어요! 벨레로폰은 샘물을 마시던 페가소스에게 살며시 굴레를 씌웠고, 페가소스는 순한 친구가 되었어요."},{"k":"img","i":7,"f":"images/scenes/c08-07.png","cap":"하늘에서 키마이라와 싸우는 장면","who":["bellerophon","pegasus","chimera"]},{"k":"who","id":"chimera"},{"k":"p","t":"리키아라는 나라에는 키마이라라는 괴물이 날뛰고 있었어요. 앞은 사자, 가운데는 염소, 꼬리는 뱀이고, 입에서는 불을 뿜었지요. 벨레로폰은 페가소스를 타고 하늘 높이 날아올라, 불길이 닿지 않는 곳에서 키마이라를 물리쳤어요."},{"k":"p","t":"하지만 벨레로폰은 점점 우쭐해졌어요. \"나는 신들처럼 올림포스까지 날아갈 수 있어!\" 벨레로폰이 페가소스를 타고 올림포스로 오르려 하자, 제우스가 작은 등에를 보내 페가소스를 따끔하게 쏘게 했어요. 깜짝 놀란 페가소스가 몸을 흔들자 벨레로폰은 땅으로 떨어졌어요. 페가소스는 혼자 올림포스로 올라가 제우스의 번개를 나르는 말이 되었고, 나중에 하늘의 별자리가 되었대요."}],"q":[{"q":"다나에를 만나려고 제우스가 변한 모습은?","o":["하얀 황소","황금 비","백조","독수리"],"a":1,"e":"제우스는 반짝이는 황금 비가 되어 청동 탑의 창문으로 스며들었어요."},{"q":"페르세우스가 그라이아이 세 자매에게서 낚아챈 것은?","o":["자루","이","눈","투구"],"a":2,"e":"세 자매가 나눠 쓰던 눈 하나를 낚아채 길을 알아냈어요."},{"q":"페르세우스는 메두사를 어떻게 보았나요?","o":["눈을 감고","방패에 비친 모습으로","뒤에서 몰래","멀리서 망원경으로"],"a":1,"e":"메두사와 눈이 마주치면 돌이 되기 때문에 아테나의 방패에 비친 모습만 보았어요."},{"q":"메두사에게서 태어난 날개 달린 말의 이름은?","o":["페가소스","케토스","키마이라","아리온"],"a":0,"e":"하얀 날개가 달린 말 페가소스는 나중에 벨레로폰의 친구가 되었어요."},{"q":"벨레로폰이 페가소스를 길들일 때 쓴 것은?","o":["황금 굴레","은 사과","마법의 피리","날개 신발"],"a":0,"e":"아테나가 꿈에 나타나 황금 굴레를 건네주었어요."}]},{"n":9,"t":"크레타의 미궁","sub":"미노타우로스와 실타래, 그리고 하늘을 난 소년","b":[{"k":"img","i":0,"f":"images/scenes/c09-00.png","cap":"장 표지","who":["theseus","ariadne","minotaur"]},{"k":"p","t":"바다 한가운데 크레타라는 커다란 섬이 있었어요. 이번 장은 이 섬에 있던 거대한 미궁 이야기예요. 미궁은 한번 들어가면 길을 잃어 다시는 나올 수 없는 복잡한 건물이에요. 이 이야기는 한 공주가 바다를 건너오면서 시작돼요."},{"k":"img","i":1,"f":"images/scenes/c09-01.png","cap":"하얀 황소 등에 타고 바다를 건너는 에우로페","who":["europa","zeus"]},{"k":"who","id":"europa"},{"k":"p","t":"페니키아의 공주 에우로페가 바닷가에서 친구들과 꽃을 따고 있을 때였어요. 눈처럼 하얀 황소 한 마리가 다가와 공주 앞에 얌전히 무릎을 꿇었어요. 에우로페가 꽃목걸이를 걸어 주고 등에 올라타자, 황소는 갑자기 바다로 뛰어들어 헤엄쳐 나갔어요! 사실 이 황소는 제우스였어요. 황소는 에우로페를 크레타섬까지 데려갔고, 에우로페는 그곳에서 세 아들을 낳았어요. 유럽을 뜻하는 '유로파'라는 이름이 바로 에우로페에게서 왔대요."},{"k":"who","id":"minos"},{"k":"p","t":"에우로페의 아들 미노스는 자라서 크레타의 왕이 되었어요. 미노스는 포세이돈에게 \"제가 왕이 될 수 있게 표시를 보내 주시면 그것을 다시 바치겠습니다\"라고 빌었어요. 그러자 바다에서 멋진 하얀 황소가 올라왔지요. 그런데 미노스는 황소가 너무 탐이 나서 약속을 어기고 다른 소를 대신 바쳤어요."},{"k":"who","id":"pasiphae"},{"k":"who","id":"minotaur"},{"k":"p","t":"화가 난 포세이돈은 미노스 왕을 벌주었어요. 얼마 뒤 왕비 파시파에가 머리는 황소, 몸은 사람인 아기를 낳았어요. 그 아이가 미노타우로스예요. 미노타우로스는 자라면서 점점 사나워져서 아무도 감당할 수가 없었어요."},{"k":"img","i":2,"f":"images/scenes/c09-02.png","cap":"다이달로스가 미궁을 설계하는 장면","who":["daedalus","minos","icarus"]},{"k":"who","id":"daedalus"},{"k":"who","id":"icarus"},{"k":"p","t":"미노스 왕은 솜씨 좋은 발명가 다이달로스를 불렀어요. 다이달로스는 아테네에서 온 사람으로, 무엇이든 만들어 내는 천재였지요. 다이달로스는 길이 이리저리 꼬이고 막다른 곳이 수없이 많은 거대한 미궁 라비린토스를 지었어요. 얼마나 복잡한지 만든 다이달로스조차 길을 잃을 뻔했대요. 미노타우로스는 그 한가운데에 갇혔어요."},{"k":"who","id":"aegeus"},{"k":"p","t":"그 무렵 크레타는 아테네와의 싸움에서 이겼어요. 미노스 왕은 아테네에 무서운 약속을 받아 냈어요. 정해진 때마다 아테네의 젊은이 열네 명을 미궁으로 보내라는 것이었지요. 미궁에 들어간 젊은이들은 아무도 돌아오지 못했어요. 아테네의 왕 아이게우스와 사람들은 슬픔에 잠겼어요."},{"k":"who","id":"theseus"},{"k":"p","t":"그때 아이게우스 왕의 아들 테세우스가 나섰어요. 테세우스는 아테네로 오는 길에 나쁜 도적들을 여럿 물리친 용감한 청년이었지요. \"제가 젊은이들과 함께 크레타로 가서 미노타우로스를 물리치겠어요!\" 떠나는 배에는 슬픔을 뜻하는 검은 돛이 달려 있었어요. 아이게우스 왕은 아들에게 부탁했어요. \"살아서 돌아온다면 하얀 돛으로 바꿔 달아 다오.\""},{"k":"img","i":3,"f":"images/scenes/c09-03.png","cap":"아리아드네가 실타래를 건네는 장면","who":["ariadne","theseus"]},{"k":"who","id":"ariadne"},{"k":"p","t":"크레타에 도착한 테세우스를 보고, 미노스 왕의 딸 아리아드네는 마음을 빼앗겼어요. 아리아드네는 다이달로스를 찾아가 미궁에서 빠져나오는 방법을 물었어요. 그리고 밤에 몰래 테세우스를 찾아가 빨간 실타래를 건넸지요. \"미궁 입구에 실 끝을 묶고 풀면서 들어가세요. 나올 때는 실을 따라오면 돼요.\""},{"k":"img","i":4,"f":"images/scenes/c09-04.png","cap":"미궁에서 실을 따라 나오는 테세우스","who":["theseus","minotaur"]},{"k":"p","t":"테세우스는 실을 풀며 어두운 미궁 속으로 들어갔어요. 꼬불꼬불한 길을 한참 지나 가장 깊은 곳에서 미노타우로스를 만났지요. 둘은 맞붙어 크게 싸웠고, 마침내 테세우스가 이겼어요. 테세우스는 실을 따라 무사히 밖으로 나왔고, 아테네의 젊은이들을 데리고 아리아드네와 함께 배를 타고 크레타를 떠났어요."},{"k":"img","i":5,"f":"images/scenes/c09-05.png","cap":"하늘을 나는 다이달로스와 이카로스","who":["daedalus","icarus"]},{"k":"p","t":"미노스 왕은 불같이 화를 냈어요. 다이달로스가 아리아드네에게 방법을 알려 준 걸 알아냈거든요. 왕은 다이달로스와 아들 이카로스를 높은 탑에 가두었어요. 하지만 다이달로스는 포기하지 않았어요. 탑에 날아든 새의 깃털을 모으고, 밀랍으로 붙여 커다란 날개 두 쌍을 만들었지요."},{"k":"p","t":"\"이카로스, 너무 낮게 날면 바닷물에 날개가 젖고, 너무 높이 날면 해의 열기에 밀랍이 녹는단다. 꼭 아빠 뒤를 따라 가운데로 날아야 해.\" 두 사람은 날개를 달고 하늘로 날아올랐어요. 처음에 이카로스는 아빠 말대로 조심조심 날았어요. 하지만 하늘을 나는 게 너무 신나서 점점 더 높이, 해를 향해 날아올랐지요. 뜨거운 햇볕에 밀랍이 녹자 깃털이 하나둘 빠졌고, 이카로스는 바다로 떨어지고 말았어요. 그 바다는 지금도 이카로스의 이름을 따서 이카리아해라고 불려요."},{"k":"img","i":6,"f":"images/scenes/c09-06.png","cap":"검은 돛을 바라보는 아이게우스","who":["aegeus"]},{"k":"p","t":"한편 테세우스는 돌아가는 길에 들른 낙소스섬에서 아리아드네와 헤어지게 되었어요. 아리아드네는 그 섬에서 디오니소스를 만나 결혼했대요. 테세우스는 슬픈 마음에 그만 아버지와의 약속을 잊어버렸어요. 배는 검은 돛을 그대로 단 채 아테네로 향했지요."},{"k":"p","t":"날마다 바닷가 언덕에서 아들을 기다리던 아이게우스 왕은 멀리 검은 돛을 보았어요. \"아들이 돌아오지 못했구나!\" 슬픔을 견디지 못한 왕은 바다에 몸을 던지고 말았어요. 그래서 그 바다는 아이게우스의 이름을 따 에게해라고 불려요. 테세우스는 아테네의 왕이 되어 나라를 지혜롭게 다스렸어요."}],"q":[{"q":"하얀 황소로 변한 제우스가 크레타로 데려간 공주는?","o":["아리아드네","에우로페","다나에","파시파에"],"a":1,"e":"유럽을 뜻하는 '유로파'라는 이름이 에우로페에게서 왔어요."},{"q":"미궁 라비린토스를 만든 발명가는?","o":["미노스","테세우스","다이달로스","헤파이스토스"],"a":2,"e":"다이달로스가 만든 미궁은 너무 복잡해서 만든 사람조차 길을 잃을 뻔했어요."},{"q":"아리아드네가 테세우스에게 건넨 것은?","o":["칼","실타래","등불","지도"],"a":1,"e":"실 끝을 입구에 묶고 풀면서 들어갔다가 실을 따라 나왔어요."},{"q":"이카로스의 날개가 망가진 까닭은?","o":["비를 맞아서","새와 부딪쳐서","해에 너무 가까이 날아 밀랍이 녹아서","너무 낮게 날아서"],"a":2,"e":"이카로스는 신이 나서 너무 높이 날다가 밀랍이 녹아 떨어지고 말았어요."},{"q":"이름이 에게해가 된 아테네의 왕은?","o":["아이게우스","미노스","테세우스","아크리시오스"],"a":0,"e":"검은 돛을 보고 아들이 죽은 줄 안 아이게우스 왕의 이름을 따서 에게해라고 불러요."}]},{"n":10,"t":"헤라클레스의 열두 과업","sub":"그리스에서 가장 힘센 영웅의 모험","b":[{"k":"img","i":0,"f":"images/scenes/c10-00.png","cap":"장 표지","who":["heracles","iolaus"]},{"k":"who","id":"heracles"},{"k":"p","t":"그리스 신화에서 가장 힘센 영웅을 꼽으라면 누구나 헤라클레스를 떠올려요. 헤라클레스는 사자 가죽을 머리에 쓰고, 커다란 올리브 나무 몽둥이를 들고 다녔지요. 이번 장에서는 헤라클레스가 해낸 열두 가지 어려운 일, 열두 과업 이야기를 들려줄게요."},{"k":"img","i":1,"f":"images/scenes/c10-01.png","cap":"요람에서 뱀 두 마리를 잡은 아기 헤라클레스","who":["heracles","alcmene","iphicles"]},{"k":"who","id":"alcmene"},{"k":"who","id":"iphicles"},{"k":"p","t":"헤라클레스는 제우스와 사람 여인 알크메네 사이에서 태어났어요. 제우스의 아내 헤라는 이 일이 몹시 못마땅했어요. 그래서 아기 헤라클레스를 아주 미워했지요. 헤라클레스가 태어난 지 여덟 달쯤 되었을 때, 헤라는 커다란 뱀 두 마리를 아기 방에 몰래 들여보냈어요. 쌍둥이 동생 이피클레스는 깜짝 놀라 울음을 터뜨렸어요. 그런데 헤라클레스는 벌떡 일어나 양손에 뱀을 한 마리씩 꽉 붙잡았어요! 엄마 알크메네가 달려왔을 때, 아기는 뱀들을 장난감처럼 들고 방긋 웃고 있었대요."},{"k":"who","id":"eurystheus"},{"k":"p","t":"헤라클레스는 자라서 누구보다 힘센 청년이 되었어요. 하지만 헤라 때문에 큰 잘못을 저지르고 말았어요. 헤라가 헤라클레스의 정신을 흐리게 해서, 소중한 가족을 해치게 만든 거예요. 정신이 돌아온 헤라클레스는 너무 슬프고 괴로웠어요. 델포이의 신탁은 이렇게 말했어요. \"미케네의 왕 에우리스테우스를 섬기며 그가 시키는 일을 열 가지 해내라. 그러면 잘못을 씻을 수 있을 것이다.\" 이 일은 나중에 열두 가지가 되었어요."},{"k":"img","i":2,"f":"images/scenes/c10-02.png","cap":"네메아의 사자와 씨름","who":["heracles","nemean_lion"]},{"k":"who","id":"nemean_lion"},{"k":"p","t":"첫 번째 과업은 네메아의 사자를 잡는 것이었어요. 이 사자는 가죽이 너무 단단해서 화살도 칼도 튕겨 나갔지요. 헤라클레스는 무기를 내려놓고 맨손으로 사자와 씨름을 해서 이겼어요. 그리고 사자의 발톱으로 가죽을 벗겨 머리에 썼어요. 그 뒤로 사자 가죽은 헤라클레스의 갑옷이 되었어요. 에우리스테우스 왕은 사자를 메고 온 헤라클레스를 보고 너무 무서워서, 커다란 청동 항아리 속에 숨었대요."},{"k":"img","i":3,"f":"images/scenes/c10-03.png","cap":"이올라오스와 함께 히드라와 싸우는 장면","who":["heracles","iolaus","hydra"]},{"k":"who","id":"iolaus"},{"k":"who","id":"hydra"},{"k":"p","t":"두 번째 과업은 레르나의 늪에 사는 머리 아홉 개 달린 물뱀 히드라를 물리치는 것이었어요. 머리 하나를 치면 그 자리에서 머리 두 개가 새로 돋아났어요! 헤라클레스는 조카 이올라오스를 불렀어요. 헤라클레스가 머리를 하나 치면, 이올라오스가 재빨리 횃불로 그 자리를 지져서 새 머리가 나지 못하게 했지요. 둘이 힘을 합쳐 마침내 히드라를 물리쳤어요. 하지만 에우리스테우스는 \"남의 도움을 받았으니 인정할 수 없다\"며 투덜거렸대요."},{"k":"p","t":"헤라클레스의 과업은 계속되었어요. 황금 뿔 달린 사슴을 1년 동안 쫓아가 붙잡았고, 커다란 멧돼지를 눈밭에 몰아 사로잡았어요. 30년 동안 한 번도 치우지 않은 아우게이아스 왕의 외양간은 강 두 개의 물줄기를 끌어들여 하루 만에 깨끗이 씻어 냈지요. 청동 부리 새 떼를 딸랑이 소리로 쫓아냈고, 크레타의 황소와 사람을 잡아먹는 말들을 붙잡았어요. 용감한 아마존 여왕 히폴리테의 허리띠를 가져오고, 세상 서쪽 끝에 사는 괴물 게리온의 붉은 소 떼도 몰고 왔어요."},{"k":"img","i":4,"f":"images/scenes/c10-04.png","cap":"헤라클레스가 아틀라스 대신 하늘을 드는 장면","who":["heracles","atlas","hesperides"]},{"k":"who","id":"hesperides"},{"k":"who","id":"atlas"},{"k":"p","t":"열한 번째 과업은 헤스페리데스 정원의 황금 사과를 가져오는 것이었어요. 이 정원은 저녁의 요정들이 지키고, 잠들지 않는 용이 사과나무를 휘감고 있었지요. 헤라클레스는 하늘을 떠받치고 있는 아틀라스를 찾아갔어요. 요정들이 아틀라스의 딸들이었거든요. \"제가 잠깐 하늘을 들고 있을 테니, 사과를 따다 주세요.\""},{"k":"p","t":"아틀라스는 기뻐하며 사과를 따 왔어요. 그런데 오랜만에 하늘에서 벗어나니 너무 홀가분했지요. \"사과는 내가 대신 갖다주마. 너는 계속 하늘을 들고 있거라.\" 헤라클레스는 꾀를 냈어요. \"좋아요. 그런데 어깨가 너무 아파서 그러는데, 잠깐만 들어 주시면 어깨에 방석을 대고 다시 들게요.\" 아틀라스가 하늘을 받아 들자, 헤라클레스는 사과를 들고 얼른 떠났어요."},{"k":"img","i":5,"f":"images/scenes/c10-05.png","cap":"케르베로스를 데리고 나오는 장면","who":["heracles","cerberus"]},{"k":"who","id":"cerberus"},{"k":"p","t":"마지막 열두 번째 과업은 가장 어려웠어요. 저승 문을 지키는 머리 셋 달린 개 케르베로스를 데려오는 것이었지요. 헤라클레스는 저승으로 내려가 하데스에게 부탁했어요. 하데스는 \"무기를 쓰지 않고 데려간다면 허락하마\"라고 했어요. 헤라클레스는 맨손으로 케르베로스를 꼭 붙잡아 땅 위로 데려왔어요. 에우리스테우스는 이번에도 항아리 속에 숨었고, 케르베로스는 다시 저승으로 돌려보내졌어요."},{"k":"img","i":6,"f":"images/scenes/c10-06.png","cap":"올림포스에서 헤베와 결혼하는 장면","who":["heracles","hebe","hera","zeus"]},{"k":"who","id":"hebe"},{"k":"p","t":"열두 과업을 모두 해낸 헤라클레스는 그 뒤로도 많은 모험을 했어요. 바위에 묶인 프로메테우스를 풀어 준 것도 헤라클레스였지요. 헤라클레스가 사람으로서의 삶을 마치자, 제우스는 그를 올림포스로 데려와 신으로 만들었어요. 그렇게 미워하던 헤라도 마침내 화를 풀고, 딸인 청춘의 여신 헤베를 헤라클레스와 결혼시켰어요. 헤라클레스는 올림포스에서 영원히 젊고 행복하게 살았대요."}],"q":[{"q":"아기 헤라클레스가 요람에서 양손에 붙잡은 것은?","o":["토끼 두 마리","뱀 두 마리","새 두 마리","사자 두 마리"],"a":1,"e":"헤라가 몰래 보낸 뱀 두 마리를 아기 헤라클레스가 꽉 붙잡았어요."},{"q":"헤라클레스가 머리에 쓰고 다닌 것은?","o":["황금 투구","네메아 사자의 가죽","월계관","날개 달린 모자"],"a":1,"e":"화살도 칼도 튕겨 내는 사자 가죽이 헤라클레스의 갑옷이 되었어요."},{"q":"히드라와 싸울 때 헤라클레스를 도운 조카는?","o":["이올라오스","이피클레스","테세우스","페르세우스"],"a":0,"e":"이올라오스가 횃불로 지져서 새 머리가 나지 못하게 했어요."},{"q":"헤라클레스 대신 황금 사과를 따 온 티탄은?","o":["크로노스","프로메테우스","아틀라스","오케아노스"],"a":2,"e":"헤라클레스가 잠깐 하늘을 들어 주는 동안 아틀라스가 사과를 따 왔어요."},{"q":"신이 된 헤라클레스와 결혼한 청춘의 여신은?","o":["헤베","헤라","아테나","이리스"],"a":0,"e":"헤라가 화를 풀고 딸 헤베를 헤라클레스와 결혼시켰어요."}]},{"n":11,"t":"테바이 이야기","sub":"용의 이빨에서 시작된 도시와 스핑크스의 수수께끼","b":[{"k":"img","i":0,"f":"images/scenes/c11-00.png","cap":"장 표지","who":["cadmus","oedipus","antigone"]},{"k":"p","t":"그리스에는 일곱 개의 문이 있는 테바이라는 도시가 있었어요. 이 도시는 어떻게 생겨났을까요? 이번 장에서는 테바이를 세운 사람과, 그 도시에서 일어난 이야기를 들려줄게요."},{"k":"who","id":"cadmus"},{"k":"p","t":"기억나나요? 9장에서 하얀 황소로 변한 제우스가 에우로페 공주를 크레타로 데려갔지요. 에우로페의 오빠 카드모스는 사라진 동생을 찾아 먼 길을 떠났어요. 아무리 찾아도 동생을 찾을 수 없자, 카드모스는 델포이의 신탁에 물었어요. \"동생은 그만 찾아라. 암소 한 마리를 따라가다가 암소가 눕는 곳에 도시를 세워라.\""},{"k":"img","i":1,"f":"images/scenes/c11-01.png","cap":"카드모스가 용의 이빨을 뿌리는 장면","who":["cadmus","athena"]},{"k":"p","t":"카드모스는 암소를 따라가다 암소가 누운 곳에 도시를 세우기로 했어요. 그런데 근처 샘물을 지키던 커다란 용이 카드모스의 부하들을 공격했어요. 카드모스는 용감히 싸워 용을 물리쳤지요. 그러자 아테나가 나타나 말했어요. \"용의 이빨을 땅에 뿌려라.\" 카드모스가 이빨을 씨앗처럼 뿌리자, 땅속에서 갑옷 입은 전사들이 쑥쑥 솟아났어요! 전사들은 서로 싸우다 다섯 명만 남았고, 이 다섯 명이 카드모스를 도와 테바이를 세웠대요."},{"k":"img","i":2,"f":"images/scenes/c11-02.png","cap":"카드모스와 하르모니아의 결혼 잔치","who":["cadmus","harmonia"]},{"k":"who","id":"harmonia"},{"k":"p","t":"카드모스는 아레스와 아프로디테의 딸 하르모니아와 결혼했어요. 결혼식에는 신들이 모두 내려와 축하했고, 무사이 여신들이 노래를 불렀어요. 사람의 결혼식에 신들이 모두 온 건 아주 드문 일이었지요. 카드모스는 그리스 사람들에게 페니키아의 글자를 가르쳐 주었다고도 해요. 이 글자가 나중에 그리스 문자가 되었대요."},{"k":"who","id":"oedipus"},{"k":"who","id":"jocasta"},{"k":"p","t":"그로부터 여러 해가 지나, 테바이의 왕 라이오스와 왕비 이오카스테 사이에 아기가 태어났어요. 그런데 신탁은 무서운 예언을 했어요. \"이 아이가 자라서 아버지를 해치게 될 것이다.\" 겁이 난 왕은 아기를 산에 버리게 했어요. 하지만 마음 착한 양치기가 아기를 구해 코린토스의 왕에게 데려갔어요. 아기가 없던 코린토스의 왕과 왕비는 아기를 자기 아들로 키웠지요. 발이 퉁퉁 부어 있어서 '부은 발'이라는 뜻의 오이디푸스라는 이름을 붙였어요."},{"k":"p","t":"어른이 된 오이디푸스는 자기가 코린토스 왕의 친아들인 줄로만 알았어요. 그런데 델포이에서 \"너는 아버지를 해치게 될 것\"이라는 예언을 듣고 깜짝 놀랐어요. 오이디푸스는 부모님을 지키려고 코린토스를 떠나 먼 길을 떠났어요. 그리고 길에서 한 노인 일행과 시비가 붙어 싸움을 벌였는데, 그 노인이 바로 친아버지 라이오스 왕이었어요. 오이디푸스는 그 사실을 꿈에도 몰랐지요."},{"k":"img","i":3,"f":"images/scenes/c11-03.png","cap":"스핑크스의 수수께끼","who":["oedipus","sphinx"]},{"k":"who","id":"sphinx"},{"k":"p","t":"오이디푸스가 테바이에 가까이 왔을 때, 도시는 큰 걱정에 빠져 있었어요. 사자의 몸에 새의 날개, 여자의 얼굴을 한 괴물 스핑크스가 바위 위에 앉아 지나가는 사람에게 수수께끼를 냈거든요. 답을 못 맞히면 살아 돌아갈 수 없었지요. 스핑크스가 오이디푸스에게 물었어요."},{"k":"p","t":"\"아침에는 네 발, 낮에는 두 발, 저녁에는 세 발로 걷는 것은 무엇이냐?\" 오이디푸스는 곰곰이 생각하다가 대답했어요. \"사람이다! 아기일 때는 네 발로 기고, 어른이 되면 두 발로 걷고, 늙으면 지팡이를 짚어 세 발로 걷지.\" 수수께끼를 풀리자 스핑크스는 바위에서 몸을 던져 사라졌어요."},{"k":"p","t":"테바이 사람들은 기뻐하며 오이디푸스를 새 왕으로 모셨어요. 오이디푸스는 왕비 이오카스테와 가족이 되어 테바이를 다스렸고, 네 아이가 태어났어요. 쌍둥이 아들 에테오클레스와 폴리네이케스, 딸 안티고네와 이스메네였지요."},{"k":"img","i":4,"f":"images/scenes/c11-04.png","cap":"눈먼 예언자 테이레시아스","who":["tiresias"]},{"k":"who","id":"tiresias"},{"k":"p","t":"몇 년 뒤 테바이에 무서운 전염병이 돌았어요. 신탁은 \"라이오스 왕을 해친 사람을 찾아내야 병이 사라진다\"고 했어요. 오이디푸스는 눈먼 예언자 테이레시아스를 불렀어요. 테이레시아스는 눈은 보이지 않았지만, 새들의 소리를 듣고 앞일과 숨겨진 진실을 알아내는 사람이었지요. 테이레시아스는 처음에는 말하지 않으려 했지만, 결국 진실을 알려 주었어요. 길에서 싸운 노인이 라이오스 왕이었고, 오이디푸스가 바로 오래전 산에 버려진 라이오스 왕의 아들이었던 거예요. 피하려고 애썼던 예언이 모두 이루어지고 말았어요. 너무나 괴로웠던 오이디푸스는 스스로 두 눈의 빛을 잃고 왕 자리에서 내려왔어요."},{"k":"img","i":5,"f":"images/scenes/c11-05.png","cap":"아버지의 손을 잡고 길을 떠나는 안티고네","who":["antigone","oedipus"]},{"k":"who","id":"antigone"},{"k":"p","t":"모두가 오이디푸스를 떠날 때, 딸 안티고네만은 곁에 남았어요. 안티고네는 눈이 보이지 않는 아버지의 손을 잡고 길을 떠났어요. 둘은 여러 해 동안 이 도시 저 도시를 떠돌았지요. 마침내 아테네 근처 콜로노스에 이르렀을 때, 아테네의 왕 테세우스가 두 사람을 따뜻하게 맞아 주었어요. 기억나나요? 미궁에서 미노타우로스를 물리친 그 테세우스예요. 오이디푸스는 그곳에서 조용히 삶을 마쳤어요."},{"k":"p","t":"안티고네는 그 뒤로도 옳다고 믿는 일을 위해 용감하게 나섰어요. 오빠 폴리네이케스가 전쟁에서 목숨을 잃었을 때, 왕은 아무도 장례를 치러 주지 못하게 했어요. 하지만 안티고네는 \"가족의 장례를 치러 주는 건 신들이 정한 도리예요\"라며 몰래 오빠를 흙으로 덮어 주었어요. 안티고네는 지금도 용기 있는 사람의 상징으로 기억되고 있어요."}],"q":[{"q":"테바이를 세운 사람은?","o":["오이디푸스","카드모스","테세우스","라이오스"],"a":1,"e":"에우로페의 오빠 카드모스가 암소가 누운 자리에 테바이를 세웠어요."},{"q":"카드모스가 땅에 뿌리자 전사들이 솟아난 것은?","o":["용의 이빨","황금 씨앗","메두사의 피","올리브 열매"],"a":0,"e":"아테나의 말대로 용의 이빨을 뿌리자 갑옷 입은 전사들이 솟아났어요."},{"q":"'아침에는 네 발, 낮에는 두 발, 저녁에는 세 발'의 답은?","o":["말","개","사람","거북"],"a":2,"e":"아기는 네 발로 기고, 어른은 두 발로 걷고, 노인은 지팡이를 짚어요."},{"q":"새들의 소리를 듣고 진실을 알아낸 눈먼 예언자는?","o":["테이레시아스","칼카스","피네우스","헬레노스"],"a":0,"e":"테이레시아스는 눈은 보이지 않았지만 앞일과 숨겨진 진실을 알았어요."},{"q":"눈이 보이지 않는 오이디푸스의 손을 잡고 함께 길을 떠난 딸은?","o":["이스메네","이오카스테","안티고네","하르모니아"],"a":2,"e":"안티고네는 끝까지 아버지 곁을 지켰어요."}]},{"n":12,"t":"황금 양털을 찾아서","sub":"아르고호를 탄 영웅들의 모험","b":[{"k":"img","i":0,"f":"images/scenes/c12-00.png","cap":"장 표지","who":["jason","medea"]},{"k":"p","t":"이번 장에서는 그리스 곳곳의 영웅들이 한 배에 모여 떠난 모험 이야기를 들려줄게요. 이 모험은 하늘을 나는 황금 양 한 마리에서 시작돼요."},{"k":"img","i":1,"f":"images/scenes/c12-01.png","cap":"황금 양을 타고 바다를 건너는 남매","who":["phrixus","helle"]},{"k":"who","id":"phrixus"},{"k":"who","id":"helle"},{"k":"who","id":"nephele"},{"k":"p","t":"보이오티아에 프릭소스와 헬레라는 남매가 살았어요. 새엄마는 남매를 몹시 미워해서 나쁜 꾀를 부렸어요. 남매가 위험에 빠지자, 구름의 요정인 친엄마 네펠레가 황금 털이 반짝이는 하늘을 나는 양을 보내 주었어요. 남매는 양의 등에 올라타 바다 위를 날아 달아났지요."},{"k":"p","t":"그런데 좁은 바다를 건널 때, 동생 헬레가 아래를 내려다보다가 그만 미끄러져 바다에 떨어지고 말았어요. 그래서 그 바다는 '헬레의 바다'라는 뜻의 헬레스폰토스라고 불리게 되었어요. 프릭소스는 무사히 멀리 콜키스라는 나라에 닿았어요."},{"k":"who","id":"aeetes"},{"k":"p","t":"콜키스의 왕 아이에테스는 프릭소스를 반갑게 맞아 주었어요. 프릭소스는 고마운 마음에 황금 양의 털가죽을 왕에게 선물했지요. 왕은 이 황금 양털을 신성한 숲의 나무에 걸어 두고, 잠들지 않는 용에게 밤낮으로 지키게 했어요."},{"k":"img","i":2,"f":"images/scenes/c12-02.png","cap":"샌들 한 짝만 신고 나타난 이아손","who":["jason","pelias"]},{"k":"who","id":"jason"},{"k":"who","id":"pelias"},{"k":"p","t":"세월이 흘러, 이올코스라는 나라에서는 펠리아스가 형의 왕 자리를 빼앗아 왕이 되어 있었어요. 펠리아스는 \"샌들을 한 짝만 신은 사람을 조심하라\"는 신탁을 들었어요. 어느 날 왕이 큰 잔치를 열었을 때, 한 청년이 샌들을 한 짝만 신고 나타났어요. 강을 건너다가 할머니를 업어 드렸는데, 그때 한 짝을 잃어버렸대요. 그 할머니는 사실 변장한 헤라 여신이었어요. 이 청년이 바로 빼앗긴 왕 자리의 주인, 이아손이었어요."},{"k":"p","t":"이아손이 왕 자리를 돌려 달라고 하자, 펠리아스는 꾀를 냈어요. \"좋다. 대신 콜키스에 있는 황금 양털을 가져오너라. 그러면 왕 자리를 돌려주마.\" 아무도 해내지 못할 거라고 생각한 거예요."},{"k":"img","i":3,"f":"images/scenes/c12-03.png","cap":"아르고호의 출항과 영웅들","who":["jason","heracles","orpheus","castor","pollux","zetes","calais"]},{"k":"who","id":"argonauts"},{"k":"who","id":"heracles"},{"k":"who","id":"orpheus"},{"k":"who","id":"castor"},{"k":"who","id":"pollux"},{"k":"p","t":"이아손은 그리스 곳곳에 소식을 보냈어요. 그러자 이름난 영웅들이 앞다투어 모여들었어요. 힘센 헤라클레스, 노래하는 오르페우스, 권투 선수 폴리데우케스와 말을 잘 타는 쌍둥이 형 카스토르, 날개 달린 쌍둥이 형제 제테스와 칼라이스까지 쉰 명쯤 되었지요. 배 만드는 솜씨가 좋은 아르고스가 아테나의 도움으로 튼튼한 배를 만들었어요. 배 이름은 '아르고호'였고, 배에 탄 영웅들은 '아르고호 원정대'라고 불렸어요. 뱃머리에는 말을 하는 신기한 나무 조각이 달려 있었대요."},{"k":"img","i":4,"f":"images/scenes/c12-04.png","cap":"날개 달린 형제가 하르피이아이를 쫓는 장면","who":["zetes","calais","harpies","phineus"]},{"k":"who","id":"phineus"},{"k":"who","id":"harpies"},{"k":"who","id":"zetes"},{"k":"who","id":"calais"},{"k":"p","t":"아르고호는 여러 섬을 지나며 모험을 계속했어요. 어느 바닷가에서는 눈먼 예언자 피네우스 왕을 만났어요. 피네우스는 밥을 먹으려고 할 때마다 새의 몸에 여자의 얼굴을 한 하르피이아이가 날아와 음식을 낚아채 가는 바람에 늘 굶주려 있었어요. 날개 달린 쌍둥이 제테스와 칼라이스가 하늘로 날아올라 하르피이아이를 멀리멀리 쫓아 버렸어요. 고마워한 피네우스는 앞으로 만날 위험을 알려 주었어요."},{"k":"img","i":5,"f":"images/scenes/c12-05.png","cap":"부딪치는 바위 사이를 지나는 배","who":["jason"]},{"k":"p","t":"\"콜키스로 가려면 서로 부딪치는 두 바위섬 사이를 지나야 한다. 먼저 비둘기를 날려 보내거라. 비둘기가 무사히 지나가면 너희도 힘껏 노를 저어 지나가라.\" 정말로 두 커다란 바위섬이 쿵 하고 부딪쳤다가 벌어지기를 되풀이하고 있었어요. 비둘기가 날아가자 바위가 부딪쳤지만, 꼬리 깃털만 조금 뜯긴 채 빠져나갔어요. 영웅들은 바위가 벌어지는 순간 온 힘을 다해 노를 저었어요. 아테나가 배를 살짝 밀어 준 덕분에 배는 뒤쪽 장식만 조금 부서진 채 무사히 지나갔어요. 그 뒤로 두 바위는 다시는 움직이지 않았대요."},{"k":"img","i":6,"f":"images/scenes/c12-06.png","cap":"메데이아가 용을 재우는 장면","who":["medea","jason","colchian_dragon"]},{"k":"who","id":"medea"},{"k":"who","id":"colchian_dragon"},{"k":"p","t":"마침내 콜키스에 도착한 이아손은 아이에테스 왕에게 황금 양털을 달라고 했어요. 왕은 불가능한 일을 시켰어요. \"불을 뿜는 청동 황소 두 마리에게 쟁기를 매어 밭을 갈고, 용의 이빨을 뿌려라.\" 그때 왕의 딸 메데이아가 이아손을 도와주었어요. 메데이아는 마법을 잘 아는 공주였거든요. 메데이아가 준 약을 바르자 이아손은 불길에도 끄떡없었고, 무사히 밭을 갈았어요. 용의 이빨에서 전사들이 솟아나자, 이아손은 그 한가운데 돌을 던져 전사들끼리 싸우게 했어요."},{"k":"p","t":"그래도 왕은 양털을 주지 않았어요. 그날 밤 메데이아는 이아손을 신성한 숲으로 데려갔어요. 메데이아가 부드러운 노래를 부르며 마법의 약을 뿌리자, 잠들지 않는다던 용이 스르르 눈을 감았어요. 이아손은 나무에 걸린 황금 양털을 얼른 거두었고, 둘은 아르고호를 타고 콜키스를 떠났어요."},{"k":"img","i":7,"f":"images/scenes/c12-07.png","cap":"청동 거인 탈로스","who":["talos","medea"]},{"k":"who","id":"talos"},{"k":"p","t":"돌아오는 길도 쉽지 않았어요. 크레타섬 앞바다에서는 청동으로 만든 거인 탈로스가 하루에 세 번 섬을 돌며 지키고 있었어요. 탈로스는 배가 다가오면 커다란 바위를 던졌지요. 탈로스의 몸에는 발목에 딱 하나 약한 곳이 있었어요. 메데이아는 마법의 노래로 탈로스를 어지럽게 만들었고, 탈로스는 발목을 바위에 부딪쳐 쓰러지고 말았어요."},{"k":"p","t":"이아손은 마침내 황금 양털을 가지고 이올코스로 돌아왔어요. 아르고호는 포세이돈에게 바쳐졌고, 나중에 하늘의 별자리가 되었대요."}],"q":[{"q":"하늘을 나는 황금 양을 타다가 바다에 떨어진 소녀는?","o":["헬레","메데이아","네펠레","이오"],"a":0,"e":"그래서 그 바다는 '헬레의 바다'라는 뜻의 헬레스폰토스라고 불려요."},{"q":"이아손이 잔치에 나타났을 때 이상한 점은?","o":["왕관을 쓰고 있었다","샌들을 한 짝만 신고 있었다","양을 데리고 왔다","날개가 달려 있었다"],"a":1,"e":"강에서 변장한 헤라를 업어 주다가 샌들 한 짝을 잃어버렸어요."},{"q":"하르피이아이를 쫓아낸 영웅들은?","o":["헤라클레스와 이올라오스","카스토르와 폴리데우케스","제테스와 칼라이스","이아손과 오르페우스"],"a":2,"e":"날개 달린 쌍둥이 제테스와 칼라이스가 하늘로 날아올라 쫓아냈어요."},{"q":"부딪치는 바위섬을 지나기 전에 먼저 날려 보낸 새는?","o":["독수리","비둘기","까마귀","부엉이"],"a":1,"e":"비둘기가 무사히 지나가는 걸 보고 영웅들도 힘껏 노를 저었어요."},{"q":"황금 양털을 지키던 용을 재운 사람은?","o":["이아손","오르페우스","메데이아","헤라"],"a":2,"e":"마법을 잘 아는 공주 메데이아가 노래와 약으로 용을 재웠어요."}]},{"n":13,"t":"사냥꾼 아탈란테","sub":"누구보다 빨리 달린 사냥꾼 소녀","b":[{"k":"img","i":0,"f":"images/scenes/c13-00.png","cap":"장 표지","who":["atalanta"]},{"k":"who","id":"atalanta"},{"k":"p","t":"영웅은 남자만 있었던 게 아니에요. 이번 장의 주인공 아탈란테는 그리스에서 가장 발이 빠르고 활을 잘 쏘는 사냥꾼이었어요."},{"k":"p","t":"아탈란테는 아기 때 산에 버려졌어요. 아들을 바랐던 아버지가 딸이 태어나자 실망했거든요. 그런데 숲속에서 엄마 곰 한 마리가 나타나 아기에게 젖을 먹이며 돌봐 주었어요. 나중에는 사냥꾼들이 아탈란테를 데려다 키웠지요. 숲에서 자란 아탈란테는 사슴보다 빨리 달리고, 누구보다 정확하게 활을 쏘았어요. 아탈란테는 사냥의 여신 아르테미스를 가장 좋아했대요."},{"k":"img","i":1,"f":"images/scenes/c13-01.png","cap":"칼리돈의 멧돼지 사냥","who":["atalanta","meleager","calydonian_boar"]},{"k":"who","id":"oeneus"},{"k":"who","id":"meleager"},{"k":"who","id":"calydonian_boar"},{"k":"p","t":"칼리돈이라는 나라의 오이네우스 왕은 신들에게 첫 수확을 바치는 제사를 지내다가, 깜빡하고 아르테미스에게만 제물을 바치지 않았어요. 화가 난 아르테미스는 집채만 한 멧돼지를 보냈어요. 멧돼지는 밭을 짓밟고 과수원을 망가뜨렸어요. 왕자 멜레아그로스는 그리스 곳곳의 영웅들을 불러 모았어요. 아르고호를 탔던 영웅들도 많이 왔지요."},{"k":"p","t":"사냥꾼들 가운데 여자는 아탈란테 한 명뿐이었어요. 몇몇 사냥꾼은 \"여자와 함께 사냥할 수는 없다\"며 투덜거렸어요. 하지만 멜레아그로스는 아탈란테의 솜씨를 믿었어요. 드디어 숲에서 멧돼지가 뛰쳐나오자, 사냥꾼들은 우왕좌왕했어요. 그때 아탈란테가 쏜 화살이 가장 먼저 멧돼지를 맞혔어요! 뒤이어 멜레아그로스가 창으로 멧돼지를 물리쳤지요. 멜레아그로스는 \"첫 화살을 맞힌 사람이 주인공\"이라며 멧돼지 가죽을 아탈란테에게 선물했어요."},{"k":"img","i":2,"f":"images/scenes/c13-02.png","cap":"황금 사과를 굴리며 달리는 경주","who":["atalanta","hippomenes","aphrodite"]},{"k":"who","id":"hippomenes"},{"k":"who","id":"aphrodite"},{"k":"p","t":"아탈란테가 유명해지자, 아버지는 딸을 다시 찾아와 결혼을 시키려고 했어요. 결혼하고 싶지 않았던 아탈란테는 조건을 걸었어요. \"나와 달리기 경주를 해서 이기는 사람과 결혼하겠어요. 하지만 지면 큰 벌을 받아야 해요.\" 많은 청년들이 도전했지만 아무도 아탈란테를 이기지 못했어요."},{"k":"p","t":"청년 히포메네스는 아탈란테를 보고 첫눈에 반했어요. 히포메네스는 사랑의 여신 아프로디테에게 도와 달라고 빌었어요. 아프로디테는 반짝이는 황금 사과 세 개를 건네며 방법을 알려 주었지요."},{"k":"p","t":"경주가 시작되자 아탈란테가 바람처럼 앞서 나갔어요. 히포메네스는 황금 사과 하나를 옆으로 굴렸어요. 반짝이는 사과가 너무 예뻐서 아탈란테는 달리다 멈추고 사과를 주웠어요. 그 틈에 히포메네스가 앞질렀지요. 아탈란테가 다시 따라잡자 두 번째 사과를, 결승선 바로 앞에서 세 번째 사과를 굴렸어요. 아탈란테가 마지막 사과를 줍는 사이, 히포메네스가 먼저 결승선을 통과했어요! 두 사람은 결혼해 함께 살았대요."}],"q":[{"q":"아기 아탈란테를 숲에서 돌봐 준 동물은?","o":["늑대","엄마 곰","사슴","염소"],"a":1,"e":"엄마 곰이 젖을 먹이며 돌봐 주었어요."},{"q":"칼리돈에 커다란 멧돼지를 보낸 여신은?","o":["헤라","아테나","아르테미스","데메테르"],"a":2,"e":"오이네우스 왕이 제물을 깜빡해서 화가 난 아르테미스가 멧돼지를 보냈어요."},{"q":"멧돼지에게 가장 먼저 화살을 맞힌 사람은?","o":["멜레아그로스","아탈란테","이아손","카스토르"],"a":1,"e":"아탈란테의 화살이 가장 먼저 맞혀서 멜레아그로스가 가죽을 선물했어요."},{"q":"히포메네스가 경주에서 굴린 것은?","o":["황금 사과","은 공","보석","꽃다발"],"a":0,"e":"아프로디테가 준 황금 사과 세 개를 굴려 아탈란테가 줍는 사이 앞질렀어요."},{"q":"히포메네스에게 황금 사과를 준 여신은?","o":["아르테미스","아테나","헤라","아프로디테"],"a":3,"e":"사랑의 여신 아프로디테가 도와주었어요."}]},{"n":14,"t":"트로이 전쟁의 씨앗","sub":"황금 사과 한 알이 큰 전쟁을 부르다","b":[{"k":"img","i":0,"f":"images/scenes/c14-00.png","cap":"장 표지","who":["paris","helen"]},{"k":"p","t":"이제부터 그리스 신화에서 가장 유명한 이야기, 트로이 전쟁이 시작돼요. 이 큰 전쟁은 놀랍게도 황금 사과 한 알에서 시작되었어요."},{"k":"who","id":"thetis"},{"k":"who","id":"peleus"},{"k":"p","t":"바다 요정 테티스는 아주 아름다워서 제우스와 포세이돈 모두 결혼하고 싶어 했어요. 그런데 이런 예언이 있었어요. \"테티스가 낳는 아들은 아버지보다 더 위대해질 것이다.\" 겁이 난 두 신은 테티스를 사람인 영웅 펠레우스와 결혼시키기로 했어요. 펠레우스는 아르고호 원정대와 칼리돈 멧돼지 사냥에도 함께했던 영웅이었지요."},{"k":"img","i":1,"f":"images/scenes/c14-01.png","cap":"결혼식장에 황금 사과를 굴리는 에리스","who":["eris","peleus","thetis"]},{"k":"who","id":"eris"},{"k":"p","t":"펠레우스와 테티스의 결혼식은 펠리온산에서 아주 성대하게 열렸어요. 올림포스의 신들이 모두 초대받았지요. 그런데 딱 한 명, 다툼과 불화의 여신 에리스만은 초대받지 못했어요. 에리스가 가는 곳마다 싸움이 일어났으니까요."},{"k":"p","t":"화가 난 에리스는 몰래 결혼식장에 찾아와 황금 사과 한 알을 잔칫상에 굴려 놓았어요. 사과에는 이렇게 쓰여 있었어요. \"가장 아름다운 여신에게.\" 그러자 헤라, 아테나, 아프로디테가 동시에 사과를 집으며 \"이건 내 거예요!\" 하고 다투기 시작했어요."},{"k":"img","i":2,"f":"images/scenes/c14-02.png","cap":"이다산의 파리스와 세 여신","who":["paris","hera","athena","aphrodite","hermes"]},{"k":"who","id":"paris"},{"k":"who","id":"hera"},{"k":"who","id":"athena"},{"k":"who","id":"aphrodite"},{"k":"p","t":"세 여신은 제우스에게 누가 가장 아름다운지 정해 달라고 했어요. 난처해진 제우스는 헤르메스에게 부탁했어요. \"이다산에 가면 파리스라는 양치기가 있다. 그 청년에게 판결을 맡기자.\" 파리스는 사실 트로이의 왕자였어요. 태어날 때 \"이 아이가 트로이를 불태울 것\"이라는 예언 때문에 산에 버려져 양치기로 자랐지요."},{"k":"p","t":"세 여신은 파리스에게 저마다 선물을 약속했어요. 헤라는 \"나를 고르면 온 세상을 다스리는 왕으로 만들어 주마\", 아테나는 \"나를 고르면 어떤 싸움에서도 지지 않는 지혜와 용기를 주마\", 아프로디테는 \"나를 고르면 세상에서 가장 아름다운 여인을 아내로 주마\"라고 했어요. 파리스는 황금 사과를 아프로디테에게 건넸어요. 헤라와 아테나는 몹시 화가 나서 트로이를 미워하게 되었어요."},{"k":"who","id":"helen"},{"k":"who","id":"menelaus"},{"k":"p","t":"세상에서 가장 아름다운 여인은 스파르타의 왕비 헬레네였어요. 헬레네에게는 이미 남편 메넬라오스 왕이 있었지요. 트로이의 왕자로 돌아간 파리스는 스파르타를 찾아갔고, 아프로디테의 도움으로 헬레네를 트로이로 데려가 버렸어요."},{"k":"who","id":"agamemnon"},{"k":"who","id":"odysseus"},{"k":"p","t":"메넬라오스는 몹시 화가 났어요. 메넬라오스의 형 미케네의 왕 아가멤논은 그리스 곳곳의 왕과 영웅들을 불러 모았어요. 오래전 헬레네의 결혼 상대를 고를 때, 구혼자들은 \"누구든 헬레네의 남편을 도와주기로\" 약속했었거든요. 이 약속을 생각해 낸 사람은 꾀 많은 이타케의 왕 오디세우스였어요. 오디세우스는 어린 아들 텔레마코스와 아내 페넬로페 곁에 남고 싶어서 꾀를 부려 보았지만 결국 들켜서 함께 떠나게 되었어요."},{"k":"img","i":3,"f":"images/scenes/c14-03.png","cap":"아기 아킬레우스를 강물에 담그는 테티스","who":["thetis","achilles"]},{"k":"who","id":"achilles"},{"k":"p","t":"그리스군에게는 꼭 필요한 영웅이 한 명 더 있었어요. 바로 펠레우스와 테티스의 아들 아킬레우스였지요. 아킬레우스가 아기였을 때, 엄마 테티스는 아들을 죽지 않는 몸으로 만들고 싶었어요. 그래서 저승의 스틱스강에 아기를 담갔지요. 하지만 테티스가 붙잡고 있던 발뒤꿈치만은 물에 젖지 않았어요. 그래서 발뒤꿈치가 아킬레우스의 단 하나 약한 곳이 되었어요. 지금도 발뒤꿈치 위의 힘줄을 '아킬레스건'이라고 불러요."},{"k":"p","t":"아킬레우스는 지혜로운 켄타우로스 케이론에게서 창 쓰는 법과 병 고치는 법을 배우며 자랐어요. 테티스는 아들이 전쟁에 나가면 목숨을 잃는다는 예언을 알고, 아킬레우스를 한 섬의 궁전에 숨겼어요. 하지만 오디세우스가 장사꾼으로 변장해 찾아와 보석과 옷 사이에 칼과 방패를 섞어 두었어요. 그때 나팔 소리가 울리자, 아킬레우스는 저도 모르게 칼과 방패를 집어 들었고 결국 정체가 드러났어요."},{"k":"img","i":4,"f":"images/scenes/c14-04.png","cap":"수많은 배의 출항","who":["agamemnon","menelaus","odysseus","achilles"]},{"k":"p","t":"마침내 그리스 곳곳에서 모인 배들이 바다를 가득 메웠어요. 1000척이 넘는 배였대요. 아가멤논이 총대장을 맡고, 메넬라오스, 오디세우스, 아킬레우스와 수많은 영웅들이 트로이를 향해 돛을 올렸어요. 이렇게 10년 동안 이어질 트로이 전쟁이 시작되었어요."}],"q":[{"q":"결혼식에 초대받지 못해 황금 사과를 굴린 여신은?","o":["헤라","에리스","아테나","닉스"],"a":1,"e":"불화의 여신 에리스가 \"가장 아름다운 여신에게\"라고 쓴 사과를 굴렸어요."},{"q":"파리스가 황금 사과를 건넨 여신은?","o":["헤라","아테나","아프로디테","아르테미스"],"a":2,"e":"아프로디테는 세상에서 가장 아름다운 여인을 아내로 주겠다고 약속했어요."},{"q":"헬레네의 남편인 스파르타의 왕은?","o":["아가멤논","메넬라오스","오디세우스","프리아모스"],"a":1,"e":"메넬라오스의 형 아가멤논이 그리스군을 불러 모았어요."},{"q":"아킬레우스의 단 하나 약한 곳은?","o":["머리","손목","발뒤꿈치","어깨"],"a":2,"e":"엄마가 붙잡고 있던 발뒤꿈치만 스틱스강 물에 젖지 않았어요."},{"q":"아킬레우스에게 창 쓰는 법과 병 고치는 법을 가르친 켄타우로스는?","o":["케이론","폴로스","네소스","실레노스"],"a":0,"e":"지혜로운 켄타우로스 케이론은 많은 영웅들의 선생님이었어요."}]},{"n":15,"t":"트로이 전쟁","sub":"10년 동안 이어진 큰 전쟁과 나무 말","b":[{"k":"img","i":0,"f":"images/scenes/c15-00.png","cap":"장 표지","who":["hector","achilles"]},{"k":"who","id":"priam"},{"k":"who","id":"hector"},{"k":"p","t":"트로이는 바닷가 언덕 위에 높은 성벽을 두른 튼튼한 도시였어요. 트로이의 왕은 늙고 지혜로운 프리아모스였고, 가장 용감한 전사는 맏아들 헥토르였지요. 그리스군은 바닷가에 배를 대고 천막을 쳤어요. 하지만 성벽이 너무 높고 튼튼해서 좀처럼 트로이를 무너뜨릴 수 없었어요. 전쟁은 9년이 넘도록 이어졌어요."},{"k":"p","t":"신들도 편을 나누었어요. 파리스에게 화가 난 헤라와 아테나, 그리고 포세이돈은 그리스 편을 들었어요. 아프로디테와 아폴론, 아레스는 트로이 편을 들었지요. 제우스는 되도록 한쪽 편을 들지 않으려고 애썼대요."},{"k":"img","i":1,"f":"images/scenes/c15-01.png","cap":"천막에서 화가 난 아킬레우스","who":["achilles","patroclus"]},{"k":"who","id":"patroclus"},{"k":"p","t":"전쟁이 10년째 되던 해, 그리스군 안에서 큰 다툼이 일어났어요. 총대장 아가멤논이 아킬레우스가 아끼던 것을 억지로 빼앗아 간 거예요. 몹시 화가 난 아킬레우스는 \"이제 싸우지 않겠다!\"며 자기 천막에 틀어박혀 버렸어요. 가장 힘센 영웅이 빠지자 그리스군은 트로이군에게 계속 밀렸어요. 헥토르가 이끄는 트로이군은 그리스의 배에 불을 지를 만큼 가까이 다가왔지요."},{"k":"p","t":"아킬레우스의 가장 친한 친구 파트로클로스는 이 모습을 보고 가만히 있을 수 없었어요. \"그럼 네 갑옷이라도 빌려줘. 내가 네 갑옷을 입고 나가면 트로이군이 너인 줄 알고 물러날 거야.\" 파트로클로스는 아킬레우스의 갑옷을 입고 전쟁터로 나가 트로이군을 몰아냈어요. 하지만 너무 멀리 쫓아가다가 헥토르와 맞서게 되었고, 끝내 돌아오지 못했어요."},{"k":"img","i":2,"f":"images/scenes/c15-02.png","cap":"성벽 위에서 인사하는 헥토르와 안드로마케","who":["hector","andromache","astyanax"]},{"k":"who","id":"andromache"},{"k":"who","id":"astyanax"},{"k":"p","t":"헥토르에게는 사랑하는 아내 안드로마케와 어린 아들 아스티아낙스가 있었어요. 헥토르가 전쟁터로 나가기 전, 성벽 위에서 가족과 인사를 나누었어요. 헥토르가 아들을 안으려고 하자, 아기는 아빠의 투구에 달린 커다란 말총 장식이 무서워서 울음을 터뜨렸어요. 헥토르와 안드로마케는 웃음을 터뜨렸고, 헥토르는 투구를 벗어 내려놓은 뒤 아들을 꼭 안아 주었어요. 전쟁 속에서도 가족을 사랑한 헥토르의 모습은 오랫동안 사람들의 마음을 울렸어요."},{"k":"img","i":3,"f":"images/scenes/c15-03.png","cap":"아킬레우스와 헥토르의 대결","who":["achilles","hector"]},{"k":"p","t":"친구를 잃은 아킬레우스는 너무 슬퍼서 크게 울었어요. 이제 아킬레우스는 다시 싸우기로 했어요. 엄마 테티스는 대장장이 신 헤파이스토스에게 부탁해 하룻밤 만에 새 갑옷과 멋진 방패를 만들어 주었어요. 방패에는 하늘과 땅과 바다, 도시와 들판의 모습이 정교하게 새겨져 있었대요."},{"k":"p","t":"아킬레우스가 전쟁터에 나타나자 트로이군은 성안으로 달아났어요. 성문 밖에는 헥토르 혼자만 남았어요. 헥토르와 아킬레우스는 성벽을 세 바퀴나 돌며 쫓고 쫓겼어요. 마침내 둘은 창과 방패를 들고 맞섰고, 이 싸움에서 아킬레우스가 이겼어요. 트로이 사람들은 가장 용감한 전사를 잃고 슬픔에 잠겼어요."},{"k":"img","i":4,"f":"images/scenes/c15-04.png","cap":"밤에 아킬레우스를 찾아간 프리아모스","who":["priam","achilles"]},{"k":"p","t":"그날 밤, 늙은 프리아모스 왕은 아무도 모르게 그리스 진영으로 향했어요. 헤르메스가 몰래 길을 안내해 주었지요. 프리아모스는 아킬레우스의 천막에 들어가 무릎을 꿇고 아킬레우스의 손을 잡았어요. \"그대의 아버지를 생각해 주오. 나도 아들을 잃은 아버지라오. 내 아들 헥토르를 돌려주시오. 장례라도 치러 주고 싶소.\""},{"k":"p","t":"아킬레우스는 멀리 고향에 있는 아버지 펠레우스가 떠올랐어요. 적이었던 두 사람은 함께 눈물을 흘렸어요. 아킬레우스는 헥토르를 돌려주고, 장례를 치르는 동안 싸우지 않겠다고 약속했어요. 트로이 전쟁 이야기에서 가장 마음이 따뜻해지는 장면이에요."},{"k":"p","t":"그 뒤 아킬레우스도 오래 살지 못했어요. 파리스가 쏜 화살이 아폴론의 도움으로 아킬레우스의 단 하나 약한 곳, 발뒤꿈치에 맞았거든요."},{"k":"img","i":5,"f":"images/scenes/c15-05.png","cap":"트로이 목마","who":["odysseus"]},{"k":"who","id":"cassandra"},{"k":"p","t":"전쟁은 여전히 끝나지 않았어요. 그때 꾀 많은 오디세우스가 좋은 생각을 해냈어요. 아주 커다란 나무 말을 만들어 속을 비우고, 그 안에 용감한 병사들을 숨기는 거예요. 나머지 그리스군은 배를 타고 떠나는 척하며 가까운 섬 뒤에 숨었어요."},{"k":"p","t":"아침이 되자 트로이 사람들은 텅 빈 바닷가와 커다란 나무 말을 보았어요. \"그리스군이 포기하고 돌아갔다! 이건 신들께 바치는 선물이야!\" 트로이 사람들은 기뻐하며 나무 말을 성안으로 끌고 들어갔어요. 예언자인 공주 카산드라가 \"저 말을 들이면 트로이가 무너져요!\"라고 외쳤지만, 아무도 믿지 않았어요. 카산드라는 앞일을 정확히 알았지만, 아폴론의 벌 때문에 아무도 카산드라의 말을 믿지 않았거든요."},{"k":"p","t":"그날 밤, 트로이 사람들이 잔치를 벌이고 잠든 사이 나무 말의 문이 열렸어요. 숨어 있던 병사들이 몰래 나와 성문을 열었고, 돌아온 그리스군이 성안으로 들어왔어요. 10년 동안 버틴 트로이가 마침내 무너지고 말았어요."},{"k":"img","i":6,"f":"images/scenes/c15-06.png","cap":"아버지를 업고 도시를 떠나는 아이네이아스","who":["aeneas","anchises"]},{"k":"who","id":"aeneas"},{"k":"who","id":"anchises"},{"k":"p","t":"불길에 휩싸인 트로이에서 한 영웅이 가족을 지키려 애썼어요. 아프로디테의 아들 아이네이아스였지요. 아이네이아스는 걷기 힘든 늙은 아버지 안키세스를 등에 업고, 어린 아들의 손을 잡고 불타는 도시를 빠져나왔어요. 살아남은 트로이 사람들과 함께 배를 타고 먼 바다로 떠난 아이네이아스는, 오랜 모험 끝에 이탈리아에 닿았어요. 로마 사람들은 아이네이아스를 자기들의 먼 조상이라고 믿었대요."}],"q":[{"q":"트로이의 가장 용감한 전사였던 프리아모스 왕의 맏아들은?","o":["파리스","헥토르","아이네이아스","헬레노스"],"a":1,"e":"헥토르는 트로이를 지킨 가장 용감한 전사였어요."},{"q":"아킬레우스의 갑옷을 빌려 입고 싸우러 나간 친구는?","o":["오디세우스","파트로클로스","아이아스","디오메데스"],"a":1,"e":"파트로클로스는 트로이군이 자기를 아킬레우스로 알고 물러나길 바랐어요."},{"q":"아기 아스티아낙스가 울음을 터뜨린 까닭은?","o":["배가 고파서","아빠 투구의 말총 장식이 무서워서","큰 소리가 나서","엄마가 떠나서"],"a":1,"e":"헥토르는 웃으며 투구를 벗고 아들을 안아 주었어요."},{"q":"트로이를 무너뜨린 오디세우스의 꾀는?","o":["땅굴 파기","커다란 나무 말","성벽 넘기","강물 막기"],"a":1,"e":"속이 빈 나무 말 안에 병사들을 숨겼어요."},{"q":"앞일을 정확히 알았지만 아무도 믿어 주지 않은 트로이의 공주는?","o":["안드로마케","헬레네","카산드라","폴릭세네"],"a":2,"e":"카산드라는 아폴론의 벌 때문에 아무도 말을 믿어 주지 않았어요."}]},{"n":16,"t":"오디세우스의 긴 귀향","sub":"10년 동안 바다를 떠돈 끝에 집으로","b":[{"k":"img","i":0,"f":"images/scenes/c16-00.png","cap":"장 표지","who":["odysseus"]},{"k":"who","id":"odysseus"},{"k":"p","t":"트로이 전쟁이 끝나고 영웅들은 저마다 고향으로 돌아갔어요. 그런데 오디세우스의 귀향길은 무려 10년이나 걸렸어요. 전쟁 10년에 귀향 10년, 오디세우스는 20년 만에야 집으로 돌아갈 수 있었지요. 그 긴 여행의 이야기를 들려줄게요."},{"k":"img","i":1,"f":"images/scenes/c16-01.png","cap":"양의 배 밑에 매달려 동굴을 빠져나가는 장면","who":["odysseus","polyphemus"]},{"k":"who","id":"polyphemus"},{"k":"p","t":"오디세우스와 부하들이 어느 섬에 내렸을 때, 커다란 동굴을 발견했어요. 동굴 안에는 치즈와 양젖이 가득했지요. 그런데 동굴의 주인이 돌아왔어요. 이마에 눈이 하나뿐인 거인, 포세이돈의 아들 폴리페모스였어요! 폴리페모스는 커다란 바위로 동굴 입구를 막아 버렸어요. 오디세우스 일행은 갇히고 말았지요."},{"k":"p","t":"오디세우스는 꾀를 냈어요. 먼저 거인에게 독한 포도주를 잔뜩 먹였어요. \"네 이름이 뭐냐?\" 거인이 묻자 오디세우스는 \"내 이름은 '아무도 아니'야\"라고 대답했어요. 거인이 곯아떨어지자, 오디세우스는 불에 달군 커다란 나무 막대로 거인의 하나뿐인 눈을 다치게 해 앞을 못 보게 했어요. 거인이 소리치자 다른 거인들이 달려와 물었어요. \"누가 널 괴롭히냐?\" \"아무도 아니가 날 괴롭혀!\" 다른 거인들은 \"아무도 아니면 괜찮네\" 하고 돌아가 버렸대요."},{"k":"p","t":"아침이 되자 폴리페모스는 양들을 풀밭에 내보내려고 바위를 치웠어요. 그리고 동굴 입구에 앉아 나가는 양들의 등을 하나하나 더듬었지요. 하지만 오디세우스와 부하들은 양의 배 밑에 꼭 매달려 있었어요. 모두 무사히 빠져나갔어요! 그런데 오디세우스가 배에서 우쭐대며 진짜 이름을 외치는 바람에, 폴리페모스의 아버지 포세이돈이 오디세우스를 미워하게 되었어요. 그래서 귀향길이 그렇게 험해졌대요."},{"k":"p","t":"바람을 다스리는 아이올로스는 오디세우스에게 거센 바람들을 모두 가둔 가죽 자루를 선물했어요. 순한 서풍만 남겨 배를 고향으로 밀어 주게 했지요. 고향 이타케가 눈앞에 보일 때쯤, 오디세우스가 잠든 사이 부하들이 자루를 열어 보았어요. 보물이 들어 있는 줄 알았거든요. 그러자 갇혀 있던 바람들이 한꺼번에 튀어나와 배를 멀리멀리 날려 보냈어요."},{"k":"img","i":2,"f":"images/scenes/c16-02.png","cap":"돼지로 변한 부하들과 키르케","who":["circe","odysseus"]},{"k":"who","id":"circe"},{"k":"p","t":"다음으로 닿은 아이아이에섬에는 마녀 키르케가 살았어요. 키르케가 준 음식을 먹은 부하들은 모두 돼지로 변해 버렸어요! 오디세우스가 부하들을 구하러 가는 길에 헤르메스가 나타나 '몰리'라는 하얀 꽃이 피는 약초를 주었어요. 이 약초 덕분에 키르케의 마법이 통하지 않자, 키르케는 부하들을 다시 사람으로 돌려주었어요. 그 뒤 오디세우스 일행은 1년 동안 키르케의 섬에서 쉬었고, 떠날 때 키르케는 앞으로 만날 위험들을 자세히 알려 주었어요."},{"k":"img","i":3,"f":"images/scenes/c16-03.png","cap":"돛대에 묶여 세이레네스의 노래를 듣는 오디세우스","who":["odysseus","seirenes"]},{"k":"who","id":"seirenes"},{"k":"p","t":"\"가장 먼저 세이레네스의 섬을 지나게 될 거예요. 세이레네스의 노래를 들으면 누구든 홀려서 그 섬으로 가게 되지요.\" 오디세우스는 부하들의 귀를 밀랍으로 막게 했어요. 그리고 자기는 노래를 꼭 들어 보고 싶어서, 부하들에게 자기 몸을 돛대에 단단히 묶게 했어요. \"내가 풀어 달라고 해도 절대 풀어 주면 안 된다!\" 아름다운 노래가 들려오자 오디세우스는 풀어 달라고 몸부림쳤지만, 부하들은 더 꽁꽁 묶고 힘차게 노를 저었어요. 배는 무사히 섬을 지나갔어요."},{"k":"img","i":4,"f":"images/scenes/c16-04.png","cap":"스킬라와 카리브디스 사이","who":["scylla","charybdis","odysseus"]},{"k":"who","id":"scylla"},{"k":"who","id":"charybdis"},{"k":"p","t":"다음은 좁은 바다였어요. 한쪽 절벽에는 머리가 여섯 개인 괴물 스킬라가, 다른 쪽에는 바닷물을 빨아들이는 거대한 소용돌이 카리브디스가 있었어요. 카리브디스에 빨려 들어가면 배가 통째로 사라지기 때문에, 오디세우스는 스킬라 쪽에 붙어 재빨리 지나가기로 했어요. 무서운 곳이었지만 오디세우스는 배를 이끌고 그곳을 빠져나갔어요. 그 뒤 태양신의 소를 잡아먹은 부하들이 벌을 받아 배가 부서졌고, 오디세우스 혼자만 살아남았어요."},{"k":"img","i":5,"f":"images/scenes/c16-05.png","cap":"칼립소의 섬에서 뗏목을 만드는 장면","who":["odysseus","calypso","hermes"]},{"k":"who","id":"calypso"},{"k":"p","t":"오디세우스는 부서진 배 조각을 붙잡고 바다를 떠돌다가, 요정 칼립소의 섬에 닿았어요. 칼립소는 오디세우스를 사랑해서 섬에 붙잡아 두었어요. \"여기서 나와 영원히 살아요. 늙지도 죽지도 않게 해 줄게요.\" 하지만 오디세우스는 날마다 바닷가에 앉아 고향과 가족을 그리워했어요. 그렇게 7년이 흘렀어요."},{"k":"p","t":"보다 못한 아테나가 제우스에게 부탁했고, 제우스는 헤르메스를 보내 오디세우스를 보내 주라고 전했어요. 칼립소는 슬펐지만 오디세우스가 뗏목을 만들 수 있게 나무와 연장을 주었어요. 오디세우스는 뗏목을 타고 다시 바다로 나섰어요."},{"k":"img","i":6,"f":"images/scenes/c16-06.png","cap":"베를 짜고 몰래 푸는 페넬로페","who":["penelope"]},{"k":"who","id":"penelope"},{"k":"who","id":"telemachus"},{"k":"p","t":"그동안 이타케에서는 아내 페넬로페가 오디세우스를 기다리고 있었어요. 오디세우스가 떠난 지 오래되자, 욕심 많은 구혼자들이 궁전에 몰려와 날마다 잔치를 벌이며 \"이제 우리 중 한 사람과 결혼하시오!\" 하고 졸랐어요. 페넬로페는 꾀를 냈어요. \"시아버지의 수의를 다 짜고 나면 결혼할 사람을 고를게요.\" 페넬로페는 낮에는 베를 짜고, 밤에는 몰래 다시 풀었어요. 그렇게 3년 동안 구혼자들을 속였지요. 어린 아기였던 아들 텔레마코스는 어느새 씩씩한 청년이 되어 아버지 소식을 찾아 나섰어요."},{"k":"img","i":7,"f":"images/scenes/c16-07.png","cap":"활시위를 당기는 오디세우스","who":["odysseus","telemachus","penelope"]},{"k":"p","t":"오랜 모험 끝에 오디세우스는 마침내 이타케에 돌아왔어요. 아테나는 오디세우스를 늙은 거지 모습으로 바꿔 주었어요. 아무도 알아보지 못했지만, 늙은 개 아르고스만은 주인을 알아보고 꼬리를 흔들었대요. 오디세우스는 아들 텔레마코스를 만나 둘만의 계획을 세웠어요."},{"k":"p","t":"페넬로페는 구혼자들에게 마지막 시험을 냈어요. \"오디세우스의 커다란 활에 시위를 걸고, 줄지어 세운 도끼 열두 개의 구멍을 화살 하나로 꿰뚫는 사람과 결혼하겠어요.\" 구혼자들은 아무도 활시위조차 걸지 못했어요. 그때 거지 차림의 오디세우스가 활을 받아 들더니, 가볍게 시위를 걸고 화살 하나로 도끼 열두 개의 구멍을 모두 꿰뚫었어요! 오디세우스는 텔레마코스와 함께 못된 구혼자들을 궁전에서 몰아냈어요."},{"k":"p","t":"페넬로페는 그래도 조심스러웠어요. 그래서 오디세우스와 둘만 아는 비밀을 물어보았어요. 오디세우스가 올리브 나무 밑동으로 만든 침대의 비밀을 이야기하자, 페넬로페는 그제야 눈물을 흘리며 남편을 끌어안았어요. 20년 만에 가족이 다시 모인 거예요."},{"k":"p","t":"이렇게 세상의 시작에서부터 영웅들의 귀향까지, 그리스 신화의 긴 이야기가 끝났어요. 이야기 속 인물들이 궁금하다면 이름을 눌러 관계도에서 더 많은 이야기를 찾아보세요."}],"q":[{"q":"폴리페모스에게 오디세우스가 말한 가짜 이름은?","o":["아무도 아니","누구든지","나그네","거인 친구"],"a":0,"e":"그래서 다른 거인들은 \"아무도 아니가 괴롭힌다\"는 말에 돌아가 버렸어요."},{"q":"오디세우스 일행은 어떻게 동굴을 빠져나갔나요?","o":["바위를 부수고","양의 배 밑에 매달려서","땅굴을 파서","거인과 친구가 되어서"],"a":1,"e":"거인은 양들의 등만 더듬어서 배 밑에 매달린 사람들을 알아채지 못했어요."},{"q":"부하들을 돼지로 바꾼 마녀는?","o":["칼립소","키르케","메데이아","헤카테"],"a":1,"e":"헤르메스가 준 약초 몰리 덕분에 오디세우스에게는 마법이 통하지 않았어요."},{"q":"세이레네스의 노래를 들을 때 오디세우스가 한 일은?","o":["귀를 막았다","돛대에 몸을 묶었다","노래를 따라 불렀다","잠을 잤다"],"a":1,"e":"부하들은 귀를 밀랍으로 막고, 오디세우스는 돛대에 묶인 채 노래를 들었어요."},{"q":"페넬로페가 구혼자들을 속인 방법은?","o":["낮에 짠 베를 밤에 몰래 풀었다","편지를 숨겼다","궁전을 떠났다","병에 걸린 척했다"],"a":0,"e":"페넬로페는 이렇게 3년 동안 구혼자들을 속였어요."}]}];
